'use strict';

// Mornay's single authored roster: 300 distinct characters, redistributed between streets, work and homes.
// Author-only network notes are never used as dialogue, flags or faction state.
// Names and flavour remain revisable; stable IDs and placements are explicit.
const MORNAY_RESIDENTS = Object.freeze([
  Object.freeze({"id":"mornay_hadrin_moss","name":"Hadrin Moss","mapId":"MORNAY_OLD_FORT_MAP","role":"watch veteran","category":"official","x":4.5,"y":4.5,"spriteType":"clerk","text":"The old removal crews called it an Istral job when people could use the road again. A head on a spear was only part of it. I still ask whether the carts got through.","facing":"right"}),
  Object.freeze({"id":"mornay_elva_tern","name":"Elva Tern","mapId":"MORNAY_OLD_FORT_MAP","role":"wall inspector","category":"resident_or_visitor","x":11.5,"y":5.5,"spriteType":"clerk","text":"Perris can mend this wall. Getting the repair approved means proving which office owns the crack. Apparently the watch owns one side and the town owns the rain.","facing":"left"}),
  Object.freeze({"id":"mornay_perris_dun","name":"Perris Dun","mapId":"MORNAY_OLD_FORT_MAP","role":"mason","category":"worker","x":5.5,"y":10.5,"spriteType":"worker","text":"These stones have been fitted more than once. See the old mortar? People like to call everything ancient. Sometimes a wall is just somebody else's repair bill.","facing":"up"}),
  Object.freeze({"id":"mornay_lotte_brin","name":"Lotte Brin","mapId":"MORNAY_OLD_FORT_MAP","role":"resident sketching","category":"resident_or_visitor","x":10.5,"y":8.5,"spriteType":"patron","text":"I learnt shading from a print of Lumina, all pale stone above the river. Here I have wet brick and Hadrin refusing to stand still. I prefer it, actually.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_maelin_rook","name":"Maelin Rook","mapId":"MORNAY_NORTH_UPPER_WEST_MAP","role":"berth steward","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"An empty berth still needs sweeping.","facing":"left"}),
  Object.freeze({"id":"mornay_corra_pike","name":"Corra Pike","mapId":"MORNAY_VALE_HOME_MAP","role":"house steward","category":"worker","x":11.5,"y":6.5,"spriteType":"worker","text":"Leave the bill with me. Mrs Vale accepts a Kethrin letter of credit from a shipping partner, but the woman who washes her curtains would prefer gold.","facing":"up"}),
  Object.freeze({"id":"mornay_fennel_ashe","name":"Fennel Ashe","mapId":"MORNAY_NORTH_UPPER_WEST_MAP","role":"gardener","category":"worker","x":9.5,"y":3.5,"spriteType":"worker","text":"The lake wind has very definite ideas about my hedges.","facing":"right"}),
  Object.freeze({"id":"mornay_nesta_vale","name":"Nesta Vale","mapId":"MORNAY_VALE_HOME_MAP","role":"shipowner's widow","category":"resident_or_visitor","x":5.5,"y":9.5,"spriteType":"patron","text":"Drynport takes its charges, Mornay takes its charges, and a damaged cargo still belongs to me. My tenants say the rents should come down. They have an answer for everything.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_osric_bell","name":"Osric Bell","mapId":"MORNAY_NORTH_UPPER_WEST_MAP","role":"retired pilot","category":"resident_or_visitor","x":6.5,"y":11.5,"spriteType":"patron","text":"A boy came off a Thornmere scow and thought he knew the Valmere. I had him watch from shore for a day. He thanked me after the wind turned.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_celda_verne","name":"Celda Verne","mapId":"MORNAY_DANE_HOME_MAP","role":"household secretary","category":"resident_or_visitor","x":10.5,"y":6.5,"spriteType":"clerk","text":"A letter from Halcyra goes straight to Mr Dane's desk. The carpenter's bill waits beneath it. I put the bill on top again when he isn't looking.","facing":"up"}),
  Object.freeze({"id":"mornay_idris_pell","name":"Idris Pell","mapId":"MORNAY_NORTH_UPPER_EAST_MAP","role":"Collegium porter","category":"worker","x":9.5,"y":5.5,"spriteType":"worker","text":"Civic Collegium. Upper pupils only. The fees prepare them for the Civic Examination, clerkships and junior service. Visitors require an appointment. You have neither pupil nor appointment with you.","facing":"right"}),
  Object.freeze({"id":"mornay_benna_lark","name":"Benna Lark","mapId":"MORNAY_NORTH_UPPER_EAST_MAP","role":"Collegium student","category":"resident_or_visitor","x":6.5,"y":4.5,"spriteType":"patron","text":"The Civic Examination itself costs very little. Mother paid for three years of preparation here. I used to think everyone meant the same thing by an inexpensive examination.","facing":"down"}),
  Object.freeze({"id":"mornay_tassel_dorn","name":"Tassel Dorn","mapId":"MORNAY_DANE_HOME_MAP","role":"domestic worker","category":"worker","x":11.5,"y":11.5,"spriteType":"worker","text":"The family visits on Dayoff, so I work on Dayoff. Mr Dane says rest is essential to clear thinking. I expect he is right; I haven't tested it lately.","facing":"right"}),
  Object.freeze({"id":"mornay_ulric_dane","name":"Ulric Dane","mapId":"MORNAY_DANE_HOME_MAP","role":"retired examiner","category":"resident_or_visitor","x":5.5,"y":9.5,"spriteType":"clerk","text":"The Examination may be open. An evening without work, a lamp and somebody to correct your answers are less evenly shared.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_dena_mere","name":"Dena Mere","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"dock representative","category":"worker","x":6.5,"y":8.5,"spriteType":"worker","text":"A missed day's pay reaches the supper table before the explanation. Nessa has kept three crews fed. That does not give anyone the right to speak for every worker here.","network":"labour associate; sympathetic, membership unconfirmed","facing":"right"}),
  Object.freeze({"id":"mornay_salwen_reed","name":"Salwen Reed","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"rope inspector","category":"resident_or_visitor","x":9.5,"y":3.5,"spriteType":"clerk","text":"Gessa wants this rope condemned. The owner wants another week from it. I have put my name beside hers.","facing":"left"}),
  Object.freeze({"id":"mornay_niva_cole","name":"Niva Cole","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"fish seller","category":"merchant","x":9.5,"y":6.5,"spriteType":"patron","text":"Heba mends the nets, I sell what comes out. The Valmere catch has farther to travel than a Thornmere basket. Pay for fresh fish while I can still honestly call it fresh.","facing":"left"}),
  Object.freeze({"id":"mornay_rulon_hart","name":"Rulon Hart","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"scow hand","category":"worker","x":9.5,"y":11.5,"spriteType":"worker","text":"We came down from Drynport with water over the bow. Lowen says the next freight will make it tonight. Lowen has a warm room and no intention of joining the crew.","facing":"up"}),
  Object.freeze({"id":"mornay_heba_flint","name":"Heba Flint","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"net mender","category":"worker","x":6.5,"y":5.5,"spriteType":"worker","text":"Ilven still ties the difficult knots at home. Pay him for them. He needs wages, not people calling him brave.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_davi_fenner","name":"Davi Fenner","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"child","category":"resident_or_visitor","x":9.5,"y":9.5,"spriteType":"child","text":"That berth looks ready. Grown-ups say looking ready isn't enough.","facing":"up"}),
  Object.freeze({"id":"mornay_merra_keld","name":"Merra Keld","mapId":"MORNAY_NORTH_LOWER_WEST_MAP","role":"laundry collector","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"The Drynport crews tie their laundry into sailcloth. Better than the clerk who sends it with a written inventory. I can count six dirty shirts without a witness.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":115},{"x":6.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_jorin_vetch","name":"Jorin Vetch","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"lodging tout","category":"worker","x":6.5,"y":4.5,"spriteType":"worker","text":"Rella has beds at the gate inn. If you need a room while you look for work, ask Della Hume. Neither price includes somebody finding you a job.","facing":"right"}),
  Object.freeze({"id":"mornay_alwen_corst","name":"Alwen Corst","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"customs messenger","category":"official","x":6.5,"y":10.5,"spriteType":"worker","text":"The packet waits over Dayoff; the urgent letters don't stop arriving. Saye marks his urgent before he reads them. I sort by departure, not by the size of the underline.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":150},{"x":6.5,"y":12.5,"pauseFrames":200}]}),
  Object.freeze({"id":"mornay_cessa_brack","name":"Cessa Brack","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"sailor's spouse","category":"worker","x":9.5,"y":8.5,"spriteType":"worker","text":"He wrote about Drynport's bridges for half a page, then asked whether the roof still leaked. I sent back a drawing of the bucket. That should answer him.","facing":"up"}),
  Object.freeze({"id":"mornay_tobin_yarrow","name":"Tobin Yarrow","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"sail repairer","category":"worker","x":9.5,"y":3.5,"spriteType":"worker","text":"Elda sends me the small sail repairs. A Valmere squall tests every stitch, so we both sign the finished patch. The captain can argue with two of us.","facing":"right"}),
  Object.freeze({"id":"mornay_ersa_vole","name":"Ersa Vole","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"discharged deckhand","category":"resident_or_visitor","x":9.5,"y":11.5,"spriteType":"traveler","text":"The boat took on less cargo and kept fewer hands. They call that the drought allowance. I asked whether my room would take less rent. It wouldn't.","facing":"left"}),
  Object.freeze({"id":"mornay_lowen_greaves","name":"Lowen Greaves","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"shipping agent","category":"worker","x":9.5,"y":5.5,"spriteType":"worker","text":"The passenger can come by coach. His grain needs a barge, a warehouse and another vessel. He keeps asking why the grain hasn't kept up with him.","facing":"down"}),
  Object.freeze({"id":"mornay_brena_sill","name":"Brena Sill","mapId":"MORNAY_NORTH_LOWER_EAST_MAP","role":"dockside baker","category":"merchant","x":6.5,"y":6.5,"spriteType":"worker","text":"Crew bread, baked firm. Honey on a loaf is extra. If somebody promised you northern sugar for that price, ask to see it before handing over your gold.","facing":"right"}),
  Object.freeze({"id":"mornay_bram_fen","name":"Bram Fen","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"warehouse tallyman","category":"worker","x":2.5,"y":6.5,"spriteType":"worker","text":"Varda keeps the signed tally. I keep the count of what actually arrived. No, those are not always the same number. You want a manifest, use the public office.","network":"confirmed member","facing":"right"}),
  Object.freeze({"id":"mornay_gessa_tarn","name":"Gessa Tarn","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"unloading forewoman","category":"worker","x":5.5,"y":6.5,"spriteType":"worker","text":"Hands clear. Set it down together. The hoist was condemned once already; ask Arlis why the contractor signed it back into use.","facing":"left"}),
  Object.freeze({"id":"mornay_halen_wick","name":"Halen Wick","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"barrel roller","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"Lume grain comes in sacks; fish goes out in barrels. I used to think round goods would be easier. You learn a great deal in your first shift.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":130},{"x":6.5,"y":12.5,"pauseFrames":180},{"x":9.5,"y":12.5,"pauseFrames":220},{"x":9.5,"y":11.5,"pauseFrames":90},{"x":9.5,"y":12.5,"pauseFrames":0},{"x":6.5,"y":12.5,"pauseFrames":0}]}),
  Object.freeze({"id":"mornay_ivara_gorse","name":"Ivara Gorse","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"freight customer","category":"resident_or_visitor","x":4.5,"y":8.5,"spriteType":"patron","text":"My reed mats came through the fen channel on a scow. Now Varda needs a harbour release and the harbour needs her receipt. The mats have rented more rooms than I have.","facing":"up"}),
  Object.freeze({"id":"mornay_petren_shaw","name":"Petren Shaw","mapId":"MORNAY_DOCK_STEPS_MAP","role":"warehouse carpenter","category":"worker","x":4.5,"y":8.5,"spriteType":"worker","text":"I build crates all day and mend our stair rail after supper. Gessa says a broken rail is a workplace hazard. I said she should tell my landlord that.","facing":"left"}),
  Object.freeze({"id":"mornay_dossa_marr","name":"Dossa Marr","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"porter","category":"worker","x":9.5,"y":4.5,"spriteType":"worker","text":"Hands clear. There's no spare set in the stores.","facing":"right"}),
  Object.freeze({"id":"mornay_vannic_hale","name":"Vannic Hale","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"scale keeper","category":"resident_or_visitor","x":13.5,"y":8.5,"spriteType":"patron","text":"Corvin at Calwick once caught a discrepancy in a damaged scale. I hear that story whenever I check ours. Useful lesson. Less useful when someone tells it while leaning on the pan.","facing":"down"}),
  Object.freeze({"id":"mornay_fenna_orl","name":"Fenna Orl","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"packet runner","category":"worker","x":9.5,"y":2.5,"spriteType":"worker","text":"Drynport packet copies go in this bundle; local receipts in that one. Put them together and somebody will send a sack of onions halfway round the lake for a signature.","facing":"left"}),
  Object.freeze({"id":"mornay_hobb_tress","name":"Hobb Tress","mapId":"MORNAY_MIDDLE_UPPER_WEST_MAP","role":"sack patcher","category":"worker","x":11.5,"y":6.5,"spriteType":"worker","text":"Gessa wants every grain sack patched before it leaves. Good. The little flour drifting out along the road belongs in somebody's supper.","facing":"down"}),
  Object.freeze({"id":"mornay_pella_dorn","name":"Pella Dorn","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"print seller","category":"merchant","x":4.5,"y":6.5,"spriteType":"patron","text":"Recipes, petitions, weather sheets. Edrin knows what I sell. A rival called them Reclaimer instructions and the watch took the lot. They have not returned the recipes either.","network":"sympathizer falsely accused of organizing violence","facing":"left"}),
  Object.freeze({"id":"mornay_orna_bex","name":"Orna Bex","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"vegetable seller","category":"merchant","x":11.5,"y":8.5,"spriteType":"patron","text":"The dry spell has made the small onions smaller. Same journey, same cart charge. Bent ones cost less; sound ones don't become bent because you dislike the price.","facing":"down"}),
  Object.freeze({"id":"mornay_micah_wren","name":"Micah Wren","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"honey dealer","category":"merchant","x":13.5,"y":6.5,"spriteType":"patron","text":"Honey. Local, and you can taste it. The finest northern sugar can cost more than gold by weight. Mrs Vale has some. I expect she keeps a close eye on her spoon.","facing":"down"}),
  Object.freeze({"id":"mornay_sova_kern","name":"Sova Kern","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"cobbler's runner","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"Hesta wants these boots back before the morning hiring. Their owner has one good pair and one chance to look ready. I'll take the short street.","facing":"up"}),
  Object.freeze({"id":"mornay_evin_rusk","name":"Evin Rusk","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"market inspector","category":"resident_or_visitor","x":9.5,"y":5.5,"spriteType":"clerk","text":"Stamped measures, please. A gold piece buys the same weight whoever holds it. I would like that to be true at every counter in Mornay.","facing":"right"}),
  Object.freeze({"id":"mornay_talma_noll","name":"Talma Noll","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"basket seller","category":"merchant","x":2.5,"y":8.5,"spriteType":"patron","text":"Fen reeds make a sound basket if you cut and dry them properly. My customers know that. The freight office insists I describe them as manufactured goods.","facing":"down"}),
  Object.freeze({"id":"mornay_ressa_muir","name":"Ressa Muir","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"shopper","category":"resident_or_visitor","x":10.5,"y":6.5,"spriteType":"patron","text":"Orna's onions, Niva's fish, then home. On Dayoff I sometimes buy a little mushroom wine. A person ought to have one errand they look forward to.","facing":"right"}),
  Object.freeze({"id":"mornay_dolen_weir","name":"Dolen Weir","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"street sweeper","category":"worker","x":9.5,"y":10.5,"spriteType":"worker","text":"Keep moving, please. The fish water reaches this gutter before the carts do.","patrol":true,"facing":"down","route":[{"x":9.5,"y":10.5,"pauseFrames":130},{"x":9.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_ansel_crowe","name":"Ansel Crowe","mapId":"MORNAY_SOUTH_ROWS_UNIT_2_MAP","role":"music teacher","category":"resident_or_visitor","x":6.5,"y":9.5,"spriteType":"clerk","text":"Everyone wants Erik Jontek's 'Shut Up and Kiss Me' tune. Vessa can play it by ear; I am still trying to persuade my pupils to count the opening beats.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_belli_hume","name":"Belli Hume","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"errand child","category":"resident_or_visitor","x":9.5,"y":9.5,"spriteType":"child","text":"Della sent me for change. Hadria says counting gold is arithmetic. Does that mean I can tell her I did my lesson at the market?","facing":"left"}),
  Object.freeze({"id":"mornay_carden_firth","name":"Carden Firth","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_WEST_MAP","role":"cloth buyer","category":"worker","x":6.5,"y":5.5,"spriteType":"worker","text":"A client wanted a coat in the latest Academy fashion. I showed her a good warm weave. She bought the fashionable one and came back for a lining.","facing":"left"}),
  Object.freeze({"id":"mornay_vessa_auld","name":"Vessa Auld","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"petition copyist","category":"worker","x":4.5,"y":8.5,"spriteType":"worker","text":"Mera Dren had neighbours, measurements and a clerk to help. People remember the petition and forget the help. Tell me what happened before paying me to make it sound official.","facing":"up"}),
  Object.freeze({"id":"mornay_torren_glass","name":"Torren Glass","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"waiting claimant","category":"worker","x":4.5,"y":6.5,"spriteType":"worker","text":"I brought measurements, just like Mera Dren. Arlis sent me to Maura; Maura sent me back. The woman in the schoolbook got an engineer. I would settle for one answer.","facing":"left"}),
  Object.freeze({"id":"mornay_helma_quist","name":"Helma Quist","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"office cleaner","category":"worker","x":6.5,"y":2.5,"spriteType":"worker","text":"They had the public benches repaired after a visiting official caught his coat. Our stairs have been loose since winter.","facing":"left"}),
  Object.freeze({"id":"mornay_arven_beck","name":"Arven Beck","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"courier","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"Calwick, Drenwick, then the fen road. The cable scow keeps the letters moving while they repair that causeway. I have carried several notices explaining how temporary it is.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":130},{"x":6.5,"y":12.5,"pauseFrames":180},{"x":9.5,"y":12.5,"pauseFrames":220},{"x":9.5,"y":11.5,"pauseFrames":90},{"x":9.5,"y":12.5,"pauseFrames":0},{"x":6.5,"y":12.5,"pauseFrames":0}]}),
  Object.freeze({"id":"mornay_nerit_wold","name":"Nerit Wold","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"examination candidate","category":"worker","x":9.5,"y":4.5,"spriteType":"worker","text":"The examination is open to everyone. The Collegium's practice papers aren't. I borrow Ulric Dane's old exercises after my shift; he marks them while I mend his fire.","facing":"up"}),
  Object.freeze({"id":"mornay_sella_croft","name":"Sella Croft","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"licence applicant","category":"worker","x":2.5,"y":8.5,"spriteType":"worker","text":"Corven says my licence needs the old receipt. The old receipt went down with the boat. Apparently that is the boat's responsibility.","facing":"up"}),
  Object.freeze({"id":"mornay_garren_yew","name":"Garren Yew","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"document carrier","category":"worker","x":11.5,"y":8.5,"spriteType":"worker","text":"The ribbon means untouched, not unimportant.","facing":"left"}),
  Object.freeze({"id":"mornay_edda_purl","name":"Edda Purl","mapId":"MORNAY_MIDDLE_UPPER_CENTRAL_EAST_MAP","role":"notice reader","category":"worker","x":12.5,"y":6.5,"spriteType":"worker","text":"The notice says petitions may be submitted by any resident. Vessa helped me read the smaller bit about copies. I can manage the first part myself now.","facing":"up"}),
  Object.freeze({"id":"mornay_varek_linn","name":"Varek Linn","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"waterworks overseer","category":"resident_or_visitor","x":2.5,"y":6.5,"spriteType":"clerk","text":"The public hydrographic office is closed. Repairs still have to be measured. Hessa and Ketta do that work in all weathers.","facing":"right"}),
  Object.freeze({"id":"mornay_hessa_dorr","name":"Hessa Dorr","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"survey assistant","category":"worker","x":5.5,"y":8.5,"spriteType":"worker","text":"Ketta reads the gauge; I check the bank. Old water marks matter more than a captain's memory. The public survey office is closed; harbour enquiries go to Maura.","facing":"left"}),
  Object.freeze({"id":"mornay_nollis_vane","name":"Nollis Vane","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"drainage worker","category":"worker","x":11.5,"y":8.5,"spriteType":"worker","text":"Less water doesn't mean less work. Silt stays where the current used to shift it. The men waiting for a full scow think we can clear the channel by arguing with it.","facing":"up"}),
  Object.freeze({"id":"mornay_ketta_roy","name":"Ketta Roy","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"gauge reader","category":"worker","x":9.5,"y":3.5,"spriteType":"worker","text":"The Thornmere reports are low again. Our own readings go in a separate book. Two falling gauges aren't an explanation; they are two things somebody needs to understand.","facing":"right"}),
  Object.freeze({"id":"mornay_ossa_fenwick","name":"Ossa Fenwick","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"pipe fitter","category":"worker","x":6.5,"y":4.5,"spriteType":"worker","text":"The contract covers the pipe. Excavating to reach the pipe is apparently a separate contract. I am waiting for a signature.","facing":"left"}),
  Object.freeze({"id":"mornay_derren_kest","name":"Derren Kest","mapId":"MORNAY_MIDDLE_UPPER_EAST_MAP","role":"water carrier","category":"worker","x":9.5,"y":10.5,"spriteType":"worker","text":"I fill these at the pump, not off the quay. Hanne at the infirmary checks. The lake being fresh water doesn't make everything that drains into it good to drink.","patrol":true,"facing":"down","route":[{"x":9.5,"y":10.5,"pauseFrames":140},{"x":9.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_berrit_fane","name":"Berrit Fane","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"cart-yard foreman","category":"worker","x":4.5,"y":8.5,"spriteType":"worker","text":"Hiring is at the East Gate. I need two sober hands tomorrow, if the freight clears. Do not pay a middleman to hear that.","facing":"up"}),
  Object.freeze({"id":"mornay_helven_moss","name":"Helven Moss","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"carter","category":"worker","x":9.5,"y":4.5,"spriteType":"worker","text":"Berrit wants the Drynport consignment moved before dark. Torlin has my spare wheel. Between them they've arranged my whole day without giving me a sound cart.","facing":"right"}),
  Object.freeze({"id":"mornay_iset_brill","name":"Iset Brill","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"peat seller","category":"merchant","x":2.5,"y":6.5,"spriteType":"patron","text":"Peat for the smokers, reeds for packing. Calwick sends the same sort of loads through the canals. Nobody puts that on a fine school map, but towns still need fuel.","facing":"right"}),
  Object.freeze({"id":"mornay_jessa_fallow","name":"Jessa Fallow","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"harness maker","category":"worker","x":12.5,"y":8.5,"spriteType":"worker","text":"Rurik keeps bringing me the same worn strap. I patch it while he saves for a new one. His mule gets Dayoff more reliably than either of us.","facing":"left"}),
  Object.freeze({"id":"mornay_rurik_dean","name":"Rurik Dean","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"teamster","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"The raised road keeps the wheels out of the fen. It also means every cart meets every other cart on the same dry strip. My mule has become very patient with fools.","facing":"left"}),
  Object.freeze({"id":"mornay_vela_thorne","name":"Vela Thorne","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"freight cook","category":"worker","x":10.5,"y":6.5,"spriteType":"worker","text":"A bowl for Kelda too. Her injury happened in this yard; the yard can feed her while they argue about wages.","facing":"down"}),
  Object.freeze({"id":"mornay_dennet_vale","name":"Dennet Vale","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"stores checker","category":"worker","x":2.5,"y":8.5,"spriteType":"worker","text":"One crate of medicine gets a clerk's escort. Ten loads of peat get me and a borrowed cart. I know which is worth more. I also know what heats the clerk's room.","facing":"right"}),
  Object.freeze({"id":"mornay_mora_wist","name":"Mora Wist","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"yard messenger","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"Berrit sends me to Hal, Hal sends me to Varda, Varda says Berrit has the paper. I can do the whole circuit before the soup goes cold now.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":145},{"x":6.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_kelda_frey","name":"Kelda Frey","mapId":"MORNAY_MIDDLE_LOWER_WEST_MAP","role":"injured porter","category":"worker","x":9.5,"y":9.5,"spriteType":"worker","text":"The foreman remembers the fall. The contractor remembers employing someone else. Yara says the ankle will take time.","facing":"right"}),
  Object.freeze({"id":"mornay_adra_kelm","name":"Adra Kelm","mapId":"MORNAY_KELM_HOME_MAP","role":"provisioner's assistant","category":"merchant","x":11.5,"y":9.5,"spriteType":"worker","text":"My brother keeps the shop; I keep our supper out of his stock tally. Neris tried counting the kitchen salt once. He won't do it twice.","facing":"left"}),
  Object.freeze({"id":"mornay_henric_sorn","name":"Henric Sorn","mapId":"MORNAY_SORN_HOME_MAP","role":"workgear hawker","category":"merchant","x":10.5,"y":8.5,"spriteType":"worker","text":"Hesta sells downstairs and I take the repaired gear round the yards. My sister says supper starts when I put the tools away. Berren is watching me closely.","facing":"right"}),
  Object.freeze({"id":"mornay_malva_teel","name":"Malva Teel","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"secondhand bookseller","category":"merchant","x":11.5,"y":8.5,"spriteType":"patron","text":"Old examination books, half price. The sums still work. Check the law questions with Mr Dane before trusting a dead clerk's certainty.","facing":"up"}),
  Object.freeze({"id":"mornay_iven_bellows","name":"Iven Bellows","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"knife sharpener","category":"worker","x":9.5,"y":3.5,"spriteType":"worker","text":"I sharpen fish knives and removal crews' blades on the same stone. Both customers need a clean edge. Only one insists on telling me the whole fight.","facing":"right"}),
  Object.freeze({"id":"mornay_essie_rann","name":"Essie Rann","mapId":"MORNAY_RANN_HOME_MAP","role":"seamstress","category":"worker","x":5.5,"y":9.5,"spriteType":"worker","text":"Jorra can sew a straight seam now. The work comes from dock families, mostly: cuffs, blankets, a coat made to last another winter. She gets her share when I am paid.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_pelren_oxley","name":"Pelren Oxley","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"customer","category":"resident_or_visitor","x":6.5,"y":4.5,"spriteType":"patron","text":"A coat for a Mornay winter, please. Not one for a gentleman walking between warm rooms in Halcyra. The lake doesn't care how well I look on arrival.","facing":"left"}),
  Object.freeze({"id":"mornay_theda_wark","name":"Theda Wark","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"lamp oil carrier","category":"worker","x":9.5,"y":10.5,"spriteType":"worker","text":"Nerit needs lamp oil for his examination reading. He asked for the smallest measure. I found a bottle that lets him carry every drop home.","patrol":true,"facing":"down","route":[{"x":9.5,"y":10.5,"pauseFrames":130},{"x":9.5,"y":12.5,"pauseFrames":180},{"x":6.5,"y":12.5,"pauseFrames":220},{"x":6.5,"y":11.5,"pauseFrames":90},{"x":6.5,"y":12.5,"pauseFrames":0},{"x":9.5,"y":12.5,"pauseFrames":0}]}),
  Object.freeze({"id":"mornay_corlen_brume","name":"Corlen Brume","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"sign painter","category":"worker","x":13.5,"y":6.5,"spriteType":"worker","text":"A merchant asked for Stonehaven grey. I told him Stonehaven says it is still grey. He paid more for the words on the pot than the colour on his sign.","facing":"down"}),
  Object.freeze({"id":"mornay_nella_gant","name":"Nella Gant","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_WEST_MAP","role":"shop sweeper","category":"worker","x":2.5,"y":8.5,"spriteType":"worker","text":"People wipe their feet while entering. Leaving seems to inspire trust.","facing":"right"}),
  Object.freeze({"id":"mornay_tavi_rusk","name":"Tavi Rusk","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"compositor","category":"worker","x":4.5,"y":8.5,"spriteType":"worker","text":"My uncle prints what he is paid to print. Do not put my words in his mouth. If you want work copied, ask at the front bench.","network":"confirmed member","facing":"up"}),
  Object.freeze({"id":"mornay_dalen_hesk","name":"Dalen Hesk","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"cooper","category":"worker","x":9.5,"y":4.5,"spriteType":"worker","text":"Fish barrels must stay tight all the way to Drynport. The empty ones come back with three different owners' marks. I know my own work by the hoops.","facing":"right"}),
  Object.freeze({"id":"mornay_savra_linnet","name":"Savra Linnet","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"forge striker","category":"worker","x":2.5,"y":6.5,"spriteType":"worker","text":"Cerren judges a weld by the sound. I keep the blows steady. Visitors ask whether we use resonance. Mostly we use a second pair of hands and stop before we're too tired.","facing":"right"}),
  Object.freeze({"id":"mornay_orenna_flint","name":"Orenna Flint","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"potter","category":"worker","x":12.5,"y":8.5,"spriteType":"worker","text":"Plain jars for Melva, bowls for Rella. The fine northern houses want matching cups. I make those after the orders people need tomorrow.","facing":"left"}),
  Object.freeze({"id":"mornay_breck_yarrow","name":"Breck Yarrow","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"carpenter apprentice","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"They give repair work to boys when the lake trade slows. Master stays until I finish. He says replacing fingers ruins the saving.","facing":"left"}),
  Object.freeze({"id":"mornay_ilma_dace","name":"Ilma Dace","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"dyer","category":"worker","x":10.5,"y":6.5,"spriteType":"worker","text":"Blue-grey for lake crews, dark cuffs for office wear. A Collegium parent wanted white. I asked whether her son intended to touch anything while he was dressed.","facing":"down"}),
  Object.freeze({"id":"mornay_korrin_ashe","name":"Korrin Ashe","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"workshop runner","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"Everybody's urgent parcel is waiting for somebody else's.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":155},{"x":6.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_verda_pike","name":"Verda Pike","mapId":"MORNAY_MIDDLE_LOWER_CENTRAL_EAST_MAP","role":"furniture repairer","category":"worker","x":2.5,"y":8.5,"spriteType":"worker","text":"I mend the chairs families bring here instead of throwing away. That one has served three children learning their letters. I would like it to survive a fourth.","facing":"right"}),
  Object.freeze({"id":"mornay_ysol_reed","name":"Ysol Reed","mapId":"MORNAY_MIDDLE_LOWER_EAST_MAP","role":"grandmother","category":"resident_or_visitor","x":2.5,"y":6.5,"spriteType":"patron","text":"My grandchildren say Dayoff starts when the school shuts. I say it starts when the washing is in. We have agreed that mine starts later.","facing":"right"}),
  Object.freeze({"id":"mornay_tessa_glyn","name":"Tessa Glyn","mapId":"MORNAY_DOCK_STEPS_UNIT_4_MAP","role":"home seamworker","category":"worker","x":6.5,"y":8.5,"spriteType":"worker","text":"Harlis says Maris reads the office replies now. Mine is still young enough to think paper is for eating. I keep the rent notice high up for both our sakes.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_loric_mallow","name":"Loric Mallow","mapId":"MORNAY_DOCK_STEPS_UNIT_1_MAP","role":"kettle repairer","category":"worker","x":6.5,"y":7.5,"spriteType":"worker","text":"People bring me kettles before they buy new ones. The good repair money comes after a freight payday. Lately I have been waiting with everybody else.","facing":"left"}),
  Object.freeze({"id":"mornay_enna_quist","name":"Enna Quist","mapId":"MORNAY_DOCK_STEPS_UNIT_1_MAP","role":"tenant","category":"worker","x":8.5,"y":9.5,"spriteType":"worker","text":"The upstairs family practise that Jontek dance on Dayoff. I am happy for them. I would be happier if happiness came down a little more softly through the ceiling.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_ferin_wold","name":"Ferin Wold","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":12.5,"y":7.5,"spriteType":"child","text":"I drew the cable scow at the broken causeway. Oren said the cable needed to reach both banks. Mine did. The people kept falling off the edge of the paper.","facing":"left","dayOff":{"mapId":"MORNAY_DOCK_STEPS_UNIT_4_MAP","x":8.5,"y":10.5,"facing":"right","pose":null}}),
  Object.freeze({"id":"mornay_bessa_marrin","name":"Bessa Marrin","mapId":"MORNAY_MIDDLE_LOWER_EAST_MAP","role":"yard gardener","category":"worker","x":5.5,"y":8.5,"spriteType":"worker","text":"We keep kitchen herbs in the yard and share them. Melva says she needs measured quantities for medicine. Fair enough; I measure supper by who's coming home.","facing":"left"}),
  Object.freeze({"id":"mornay_sima_wold","name":"Sima Wold","mapId":"MORNAY_SOUTH_UPPER_WEST_MAP","role":"inn proprietor on errands","category":"resident_or_visitor","x":4.5,"y":8.5,"spriteType":"patron","text":"Rella keeps the inn running. People leave letters there for neighbours who cannot safely receive them at work. A closed envelope is still closed when an officer holds it.","network":"boarding and lodging associate","facing":"up"}),
  Object.freeze({"id":"mornay_gerris_cove","name":"Gerris Cove","mapId":"MORNAY_SOUTH_UPPER_WEST_MAP","role":"itinerant repairer","category":"worker","x":9.5,"y":4.5,"spriteType":"worker","text":"Drenwick has the same loose hinges as Mornay, just fewer stairs between them. I bring small tools. There is always somebody with a door they have been meaning to mend.","facing":"right"}),
  Object.freeze({"id":"mornay_rona_kett","name":"Rona Kett","mapId":"MORNAY_SOUTH_UPPER_WEST_MAP","role":"bread carrier","category":"worker","x":2.5,"y":6.5,"spriteType":"worker","text":"The warm loaves go first. I carry the disappointment home.","facing":"right"}),
  Object.freeze({"id":"mornay_hollis_pate","name":"Hollis Pate","mapId":"MORNAY_PATE_HOME_MAP","role":"retired cook","category":"resident_or_visitor","x":9.5,"y":9.5,"spriteType":"patron","text":"At the inn I learnt to boil water before worrying about seasoning. Selven would approve. Sit down if your feet hurt; supper can have another opinion at the table.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_tilda_mere","name":"Tilda Mere","mapId":"MORNAY_SOUTH_UPPER_WEST_MAP","role":"dockworker's sister","category":"worker","x":12.5,"y":8.5,"spriteType":"worker","text":"Dena remembers everyone's wages and forgets her own lunch.","facing":"left"}),
  Object.freeze({"id":"mornay_vennel_saye","name":"Vennel Saye","mapId":"MORNAY_COURT_UNIT_3_MAP","role":"clerk's parent","category":"resident_or_visitor","x":6.5,"y":7.5,"spriteType":"clerk","text":"Edrin passed his examinations at this table. We cleared the supper things so he could study. I am proud of him. It would still be nice to receive an ordinary letter.","facing":"left"}),
  Object.freeze({"id":"mornay_kessa_tern","name":"Kessa Tern","mapId":"MORNAY_SOUTH_ROWS_MAP","role":"boardinghouse maid","category":"worker","x":11.5,"y":7.5,"spriteType":"worker","text":"Four workdays and Dayoff, unless the tenants all want fresh linen on the fifth. Then I rest when the sheets are dry. I don't mind the children helping with the pegs.","facing":"right"}),
  Object.freeze({"id":"mornay_orvin_clay","name":"Orvin Clay","mapId":"MORNAY_SOUTH_UPPER_WEST_MAP","role":"furniture mover","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"It came through that door once. This comforts nobody.","facing":"left"}),
  Object.freeze({"id":"mornay_jalda_firth","name":"Jalda Firth","mapId":"MORNAY_SOUTH_ROWS_UNIT_4_MAP","role":"travelling aunt","category":"resident_or_visitor","x":6.5,"y":8.5,"spriteType":"traveler","text":"My nephew passed the Civic Examination and waited a year for a vacancy. His first letter was all about the desk. His second asked whether I could send a warm blanket.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_fenric_dorr","name":"Fenric Dorr","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"road guide","category":"worker","x":2.5,"y":6.5,"spriteType":"worker","text":"For Calwick, keep to the raised fen road and ask after the crossings. A dry month doesn't turn the marsh into firm ground. I've seen people learn that with a loaded cart.","facing":"right"}),
  Object.freeze({"id":"mornay_selma_greaves","name":"Selma Greaves","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"lunch seller","category":"merchant","x":9.5,"y":10.5,"spriteType":"worker","text":"Sit and eat. Vela sends the empty bowls back from the yard, so I know how many hands got hired. Fewer bowls this week. More people asking the price first.","patrol":true,"facing":"down","route":[{"x":9.5,"y":10.5,"pauseFrames":130},{"x":9.5,"y":12.5,"pauseFrames":180},{"x":6.5,"y":12.5,"pauseFrames":220},{"x":6.5,"y":11.5,"pauseFrames":90},{"x":6.5,"y":12.5,"pauseFrames":0},{"x":9.5,"y":12.5,"pauseFrames":0}]}),
  Object.freeze({"id":"mornay_torva_dale","name":"Torva Dale","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"pack repairer","category":"worker","x":5.5,"y":8.5,"spriteType":"worker","text":"The strap failed where you kept telling yourself it would hold.","facing":"left"}),
  Object.freeze({"id":"mornay_ilda_stern","name":"Ilda Stern","mapId":"MORNAY_STERN_HOME_MAP","role":"traveller","category":"resident_or_visitor","x":9.5,"y":9.5,"spriteType":"traveler","text":"My sister Melva keeps a bed for me above her shop. I saved for a rail journey once, then spent it on our mother's roof. Mother says the view from a dry room is quite good.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_brannic_hume","name":"Brannic Hume","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"wagon guard","category":"worker","x":9.5,"y":3.5,"spriteType":"worker","text":"The merchant's letter travels ahead. I guard the load that follows. He has already complained from his inn that we are late. We met the same shallow channel as everyone else.","facing":"right"}),
  Object.freeze({"id":"mornay_melli_voss","name":"Melli Voss","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"market child","category":"resident_or_visitor","x":6.5,"y":4.5,"spriteType":"child","text":"That man sells maps. I think he is lost.","facing":"left"}),
  Object.freeze({"id":"mornay_oswen_lark","name":"Oswen Lark","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"letter writer","category":"worker","x":13.5,"y":6.5,"spriteType":"worker","text":"Elva sends gold to her son when the crew is idle. He sends it back when he's paid. I write the letters and leave the little quarrel about who needs it more exactly as they say it.","facing":"down"}),
  Object.freeze({"id":"mornay_delra_tress","name":"Delra Tress","mapId":"MORNAY_SOUTH_UPPER_EAST_MAP","role":"jug seller","category":"merchant","x":2.5,"y":8.5,"spriteType":"patron","text":"Hold the base as well. That advice comes free.","facing":"right"}),
  Object.freeze({"id":"mornay_jessa_nair","name":"Jessa Nair","mapId":"MORNAY_WEST_GATE_MAP","role":"watch sergeant","category":"official","x":9.5,"y":12.5,"spriteType":"clerk","text":"Keep the gateway clear. We have orders to ask about Reclaimer printers. A labour complaint is not an answer to that question, whatever some employers tell us.","facing":"left"}),
  Object.freeze({"id":"mornay_anric_fell","name":"Anric Fell","mapId":"MORNAY_WEST_GATE_MAP","role":"watch constable","category":"official","x":9.5,"y":5.5,"spriteType":"clerk","text":"Directions cost nothing. Please stop offering me coins.","facing":"down"}),
  Object.freeze({"id":"mornay_porrin_beck","name":"Porrin Beck","mapId":"MORNAY_WEST_GATE_MAP","role":"road porter","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"Rella keeps a chair near the inn door for people who have walked the fen road. I'll get this bag there. Its owner is coming at his own pace.","patrol":true,"facing":"down","route":[{"x":6.5,"y":10.5,"pauseFrames":175},{"x":6.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_vilda_thorn","name":"Vilda Thorn","mapId":"MORNAY_WEST_GATE_MAP","role":"returning resident","category":"resident_or_visitor","x":5.5,"y":6.5,"spriteType":"patron","text":"A week in Calwick and I could hear myself think. Here the carts start before dawn. I missed the noise, though I won't admit that to my neighbours.","facing":"left"}),
  Object.freeze({"id":"mornay_dalven_rill","name":"Dalven Rill","mapId":"MORNAY_EAST_GATE_MAP","role":"freight watch","category":"official","x":6.5,"y":12.5,"spriteType":"clerk","text":"Declare the load before unloading. If someone offers to lose the excise copy for a fee, remember whose hand took the money.","facing":"right"}),
  Object.freeze({"id":"mornay_meret_shaw","name":"Meret Shaw","mapId":"MORNAY_EAST_GATE_MAP","role":"wagon checker","category":"worker","x":11.5,"y":8.5,"spriteType":"worker","text":"A loose wheel is not a local administrative custom.","facing":"down"}),
  Object.freeze({"id":"mornay_varen_noll","name":"Varen Noll","mapId":"MORNAY_EAST_GATE_MAP","role":"delivery driver","category":"worker","x":9.5,"y":10.5,"spriteType":"worker","text":"A parcel for Mrs Vale, another for the shared court. The first has a seal and three lines of address. The second says 'ask Selda'. Selda is usually quicker.","patrol":true,"facing":"down","route":[{"x":9.5,"y":10.5,"pauseFrames":180},{"x":9.5,"y":12.5,"pauseFrames":180}]}),
  Object.freeze({"id":"mornay_hilda_vane","name":"Hilda Vane","mapId":"MORNAY_EAST_GATE_MAP","role":"animal minder","category":"worker","x":9.5,"y":9.5,"spriteType":"worker","text":"Let him smell your hand. He has had a day of strangers.","facing":"right"}),
  Object.freeze({"id":"mornay_cressa_mote","name":"Cressa Mote","mapId":"MORNAY_EAST_GATE_MAP","role":"exhausted traveller","category":"resident_or_visitor","x":6.5,"y":9.5,"spriteType":"traveler","text":"Drynport is all steps and bridges. I thought I would have a rest from climbing in Mornay. Della says the room she has is upstairs. Of course it is.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_marit_voss","name":"Marit Voss","mapId":"MORNAY_OFFICE_MAP","role":"senior officer","category":"official","x":3.5,"y":2.5,"spriteType":"clerk","text":"Reclaimer sheets have reached three wards. We want evidence of offences, not a list of people your employer dislikes. Harbour matters still go to Saye. I will not sign for his department.","facing":"down"}),
  Object.freeze({"id":"mornay_inessa_cray","name":"Inessa Cray","mapId":"MORNAY_OFFICE_MAP","role":"reception clerk","category":"official","x":2.5,"y":6.5,"spriteType":"clerk","text":"Imperial credentials? Regional enquiries begin here. A credential does not make the responsible desk available. State the office you need.","facing":"down"}),
  Object.freeze({"id":"mornay_halden_quill","name":"Halden Quill","mapId":"MORNAY_OFFICE_MAP","role":"records supervisor","category":"official","x":11.5,"y":2.5,"spriteType":"worker","text":"A cargo record belongs with the harbour. An Imperial liability claim belongs here. Please keep both receipts. Nobody benefits from discovering that the other office kept the only copy.","facing":"down"}),
  Object.freeze({"id":"mornay_bera_senn","name":"Bera Senn","mapId":"MORNAY_OFFICE_MAP","role":"payments clerk","category":"official","x":5.5,"y":6.5,"spriteType":"clerk","text":"The fee is posted. The contractor's handling charge is separate. No, this office does not issue a receipt for his portion.","facing":"down"}),
  Object.freeze({"id":"mornay_eldric_fane","name":"Eldric Fane","mapId":"MORNAY_OFFICE_MAP","role":"requisitions clerk","category":"official","x":10.5,"y":6.5,"spriteType":"clerk","text":"Aldric at Calwick returns requisitions with every missing tool marked. Our contractor calls that obstructive. I call it a list we shall eventually have to pay for.","facing":"down"}),
  Object.freeze({"id":"mornay_novra_dain","name":"Novra Dain","mapId":"MORNAY_OFFICE_MAP","role":"registration administrator","category":"official","x":13.5,"y":6.5,"spriteType":"clerk","text":"The Education Act opens the ward school to a child whose family wants a place. Missing papers shouldn't close it again. Oren sends a neighbour who can vouch for the family; we begin there.","facing":"down"}),
  Object.freeze({"id":"mornay_coris_wren","name":"Coris Wren","mapId":"MORNAY_OFFICE_MAP","role":"archive assistant","category":"official","x":13.5,"y":4.5,"spriteType":"worker","text":"Old freight books record water levels beside the loads. Ketta asked for copies. I leave the mud stains in the margins; sometimes they tell you why the clerk stopped writing.","facing":"right"}),
  Object.freeze({"id":"mornay_lenva_purl","name":"Lenva Purl","mapId":"MORNAY_OFFICE_MAP","role":"appointment clerk","category":"official","x":4.5,"y":8.5,"spriteType":"clerk","text":"An examination pass makes you eligible for a post. It doesn't make a vacant desk appear. I waited nine months for mine. Please put a current address on the application.","facing":"left"}),
  Object.freeze({"id":"mornay_torben_clay","name":"Torben Clay","mapId":"MORNAY_OFFICE_MAP","role":"building porter","category":"worker","x":12.5,"y":12.5,"spriteType":"worker","text":"That door sticks. Please blame the door before the Empire.","facing":"left"}),
  Object.freeze({"id":"mornay_messa_yule","name":"Messa Yule","mapId":"MORNAY_OFFICE_MAP","role":"copy clerk","category":"official","x":4.5,"y":11.5,"spriteType":"clerk","text":"I copied the contractor's complaint twice. Both copies call the same dismissed porter a different kind of threat.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_arlis_rook","name":"Arlis Rook","mapId":"MORNAY_OFFICE_MAP","role":"infrastructure liaison","category":"official","x":9.5,"y":4.5,"spriteType":"worker","text":"The hoist certificate is a contractor matter. If Gessa contests it, she must provide another inspection. This desk cannot suspend an authorized contract on hearsay.","facing":"down"}),
  Object.freeze({"id":"mornay_wenda_flax","name":"Wenda Flax","mapId":"MORNAY_OFFICE_MAP","role":"payroll petitioner","category":"worker","x":2.5,"y":10.5,"spriteType":"worker","text":"Three weeks of unpaid work. Bera says the signature is missing. My replacement had somebody to speak for him; his pay went through. I have brought my own timesheets again.","facing":"right"}),
  Object.freeze({"id":"mornay_corven_dace","name":"Corven Dace","mapId":"MORNAY_OFFICE_MAP","role":"licence officer","category":"official","x":11.5,"y":8.5,"spriteType":"clerk","text":"A licence has to survive being read by a different officer. You may dislike the wording; I dislike parts of it myself. But I won't sell you a paper the next desk can dismiss.","facing":"down"}),
  Object.freeze({"id":"mornay_helis_tarn","name":"Helis Tarn","mapId":"MORNAY_OFFICE_MAP","role":"archive conservator","category":"official","x":1.5,"y":4.5,"spriteType":"worker","text":"We dry the books a few leaves at a time. The oldest water records are the first people ask for when the water behaves strangely. They were less interested in paying to keep the roof sound.","facing":"up"}),
  Object.freeze({"id":"mornay_nerin_gant","name":"Nerin Gant","mapId":"MORNAY_OFFICE_MAP","role":"junior examiner","category":"official","x":10.5,"y":11.5,"spriteType":"clerk","text":"Mera Dren used the Water Access Clause. The examination asks which statute. I ask candidates who took the measurements, and whether a clerk helped. That part matters when you actually have the job.","facing":"up"}),
  Object.freeze({"id":"mornay_vessa_lund","name":"Vessa Lund","mapId":"MORNAY_OFFICE_MAP","role":"public assistant","category":"official","x":6.5,"y":10.5,"spriteType":"worker","text":"Tell me what happened in your own words. The IJC can establish facts about Imperial funds or responsibility; it isn't a court for every quarrel. I can at least help you address the right desk.","facing":"left"}),
  Object.freeze({"id":"mornay_yara_kelm","name":"Yara Kelm","mapId":"MORNAY_INFIRMARY_MAP","role":"senior nurse","category":"service","x":3.5,"y":6.5,"spriteType":"clerk","text":"Rest is treatment. Nessa brings clean linen when the stores run short; I do not ask whose meetings she attends. No one gets to use a patient's bed as a political favour.","network":"medical mutual-aid associate","facing":"left"}),
  Object.freeze({"id":"mornay_selven_orr","name":"Selven Orr","mapId":"MORNAY_INFIRMARY_MAP","role":"physician","category":"service","x":5.5,"y":2.5,"spriteType":"clerk","text":"We clean, bind and watch the wound. The ward charges one gold for each point of health restored. You may pay for what you can afford. Tell me who needs care.","service":"treatment","facing":"down"}),
  Object.freeze({"id":"mornay_hanne_brist","name":"Hanne Brist","mapId":"MORNAY_INFIRMARY_MAP","role":"infirmary steward","category":"service","x":3.5,"y":3.5,"spriteType":"worker","text":"Eight beds, clean water and enough linen to change them. Those are my first requests. Yara can make a small stock last, but she shouldn't have to do it every week.","facing":"down"}),
  Object.freeze({"id":"mornay_elrin_vey","name":"Elrin Vey","mapId":"MORNAY_INFIRMARY_MAP","role":"registered Bloommarked healer","category":"service","x":9.5,"y":3.5,"spriteType":"clerk","text":"I am the registered Bloommarked healer. Resonance can support damaged tissue; it cannot replace a clean wound, food or sleep. Selven directs the care. I cannot mend a working life in an afternoon.","hairColor":"#72ac7b","facing":"down"}),
  Object.freeze({"id":"mornay_jonna_mire","name":"Jonna Mire","mapId":"MORNAY_INFIRMARY_MAP","role":"dispenser","category":"service","x":12.5,"y":2.5,"spriteType":"worker","text":"Melva's potions can keep a hurt traveller on their feet long enough to reach us. They haven't put a broken bone back together on the road. Selven still needs to examine it.","facing":"right"}),
  Object.freeze({"id":"mornay_padris_kett","name":"Padris Kett","mapId":"MORNAY_INFIRMARY_MAP","role":"orderly","category":"service","x":6.5,"y":8.5,"spriteType":"worker","text":"Fressa got home, then found she couldn't manage the stairs. We practised them here before she tried again. People think leaving the ward is the end of the work.","facing":"left"}),
  Object.freeze({"id":"mornay_lessa_fern","name":"Lessa Fern","mapId":"MORNAY_INFIRMARY_MAP","role":"trainee nurse","category":"service","x":12.5,"y":6.5,"spriteType":"clerk","text":"Yara makes me wash again when I touch the wrong cloth. I used to think she was being severe. Then I watched how carefully she does it herself, even after a whole night here.","facing":"right"}),
  Object.freeze({"id":"mornay_nevin_brack","name":"Nevin Brack","mapId":"MORNAY_INFIRMARY_MAP","role":"patient with crushed foot","category":"worker","x":1.5,"y":6.5,"spriteType":"worker","text":"The hoist slipped. Gessa stopped the shift; the owner says she overreacted. I would like him to stand on this foot before deciding.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_elma_pike","name":"Elma Pike","mapId":"MORNAY_SOUTH_ROWS_UNIT_4_MAP","role":"patient's partner","category":"worker","x":8.5,"y":10.5,"spriteType":"worker","text":"Nevin wants to get back to the quay. I want him to be able to stand without gripping the bed. Gessa sent word that she knows which of us is right.","facing":"right"}),
  Object.freeze({"id":"mornay_dorran_bale","name":"Dorran Bale","mapId":"MORNAY_INFIRMARY_MAP","role":"recovering boat hand","category":"worker","x":10.5,"y":10.5,"spriteType":"worker","text":"Something struck us on the fen road. I did not see enough to give it a name. The nurse needs the wound cleaned, not another story about it.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_mirren_ashe","name":"Mirren Ashe","mapId":"MORNAY_SOUTH_ROWS_UNIT_3_MAP","role":"exhausted caregiver","category":"worker","x":6.5,"y":7.5,"spriteType":"worker","text":"The ward sent Fressa home with instructions I can read. That helps. A neighbour takes my place when I need the market. I am beginning to get a little sleep again.","facing":"left"}),
  Object.freeze({"id":"mornay_vela_rinn","name":"Vela Rinn","mapId":"MORNAY_INFIRMARY_MAP","role":"cook","category":"service","x":13.5,"y":12.5,"spriteType":"worker","text":"Broth, soft grain, a little mushroom when Selven allows it. Good food for getting your strength back. I save the mushroom wine for my own Dayoff.","facing":"right"}),
  Object.freeze({"id":"mornay_jessin_corst","name":"Jessin Corst","mapId":"MORNAY_INFIRMARY_MAP","role":"linen orderly","category":"service","x":4.5,"y":11.5,"spriteType":"worker","text":"Fenric brings linen from Nessa's laundry. I count the clean sheets before the beds need changing. We've learnt not to wait for the accounts office to finish agreeing with itself.","facing":"up"}),
  Object.freeze({"id":"mornay_teren_lume","name":"Teren Lume","mapId":"MORNAY_INFIRMARY_MAP","role":"night nurse","category":"service","x":9.5,"y":8.5,"spriteType":"clerk","text":"More road injuries this month. More lifting injuries too. We record both; counting only the frightening ones would leave half the beds unexplained.","facing":"right"}),
  Object.freeze({"id":"mornay_orla_nair","name":"Orla Nair","mapId":"MORNAY_INFIRMARY_MAP","role":"watch constable visiting colleague","category":"official","x":12.5,"y":11.5,"spriteType":"clerk","text":"She complains properly now. That is an improvement.","facing":"left"}),
  Object.freeze({"id":"mornay_fressa_dean","name":"Fressa Dean","mapId":"MORNAY_SOUTH_ROWS_UNIT_3_MAP","role":"discharged patient","category":"worker","x":10.5,"y":8.5,"spriteType":"worker","text":"Yara says a little more walking each day. Mirren waits at the landing so I don't have to pretend I am managing. I'd like to carry her shopping again someday.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_pelda_hesk","name":"Pelda Hesk","mapId":"MORNAY_INFIRMARY_MAP","role":"patient's mother","category":"resident_or_visitor","x":3.5,"y":11.5,"spriteType":"patron","text":"They explained the dressing slowly, then let me practise. I had expected to be sent away until visiting time. Now I can do something useful when he comes home.","facing":"right"}),
  Object.freeze({"id":"mornay_vanis_teal","name":"Vanis Teal","mapId":"MORNAY_INFIRMARY_MAP","role":"infirmary accountant","category":"service","x":11.5,"y":3.5,"spriteType":"clerk","text":"The ordinary ward accounts for nearly all our work. The resonance allocation is limited. People hear the healer's title and imagine we have no other expenses.","facing":"left"}),
  Object.freeze({"id":"mornay_neris_kelm","name":"Neris Kelm","mapId":"MORNAY_PROVISIONER_MAP","role":"provisioner","category":"merchant","x":3.5,"y":3.5,"spriteType":"worker","text":"Potion or bait? Prices are marked. Yara's infirmary order is already set aside; the counter stock is for anyone with the coin.","service":"provisioner","facing":"down"}),
  Object.freeze({"id":"mornay_eldra_fenn","name":"Eldra Fenn","mapId":"MORNAY_PROVISIONER_MAP","role":"stockkeeper","category":"resident_or_visitor","x":2.5,"y":6.5,"spriteType":"patron","text":"The jars nearest the front came first. This dry spell has delayed enough orders without us wasting the stock that did arrive. Check the seals before packing.","facing":"right"}),
  Object.freeze({"id":"mornay_pavin_marr","name":"Pavin Marr","mapId":"MORNAY_PROVISIONER_MAP","role":"counter assistant","category":"worker","x":5.5,"y":3.5,"spriteType":"worker","text":"If you need the small measure, ask for the small measure.","facing":"down"}),
  Object.freeze({"id":"mornay_linna_bexley","name":"Linna Bexley","mapId":"MORNAY_PATE_HOME_MAP","role":"household shopper","category":"resident_or_visitor","x":11.5,"y":11.5,"spriteType":"patron","text":"Hollis taught me to stretch a pot with grain and mushrooms. It works until the grain price rises too. Then we take turns pretending we wanted a smaller helping.","facing":"up"}),
  Object.freeze({"id":"mornay_heddin_wist","name":"Heddin Wist","mapId":"MORNAY_PROVISIONER_MAP","role":"travelling labourer","category":"resident_or_visitor","x":5.5,"y":7.5,"spriteType":"traveler","text":"I can read the hiring notice, thanks to the Education Act. It says there may be work tomorrow. Reading it twice doesn't make it promise anything more.","facing":"up"}),
  Object.freeze({"id":"mornay_toria_brume","name":"Toria Brume","mapId":"MORNAY_PROVISIONER_MAP","role":"provision packer","category":"worker","x":11.5,"y":6.5,"spriteType":"worker","text":"These plain jars go to Yara's ward. I pack each one separately. A delayed boat is bad enough without delivering a box of broken medicine when it finally gets here.","facing":"right"}),
  Object.freeze({"id":"mornay_keven_muir","name":"Keven Muir","mapId":"MORNAY_PROVISIONER_MAP","role":"kitchen buyer","category":"worker","x":4.5,"y":10.5,"spriteType":"worker","text":"The Ledger House wants northern sugar for a guest. Odrin can make a good pudding with honey. The guest wants the expensive word on the bill as much as the taste.","facing":"left"}),
  Object.freeze({"id":"mornay_yenna_vetch","name":"Yenna Vetch","mapId":"MORNAY_SOUTH_ROWS_UNIT_1_MAP","role":"neighbour collecting order","category":"worker","x":8.5,"y":9.5,"spriteType":"worker","text":"Rissa watches my little ones while I collect our orders. I bring her mother's medicine back too. That's how two households manage an ordinary market morning.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_melva_stern","name":"Melva Stern","mapId":"MORNAY_APOTHECARY_MAP","role":"apothecary","category":"merchant","x":11.5,"y":3.5,"spriteType":"worker","text":"Potions for the road, properly labelled compounds for the ward. Tell me what you need. None of these replaces cleaning a wound, and a larger dose isn't automatically a better one.","service":"apothecary","facing":"down"}),
  Object.freeze({"id":"mornay_arret_cole","name":"Arret Cole","mapId":"MORNAY_APOTHECARY_MAP","role":"apprentice","category":"worker","x":3.5,"y":5.5,"spriteType":"worker","text":"Melva has me copy the recipe before measuring anything. The reading lessons I complained about are proving useful. So is admitting when I can't make out a number.","facing":"down"}),
  Object.freeze({"id":"mornay_vessa_gorse","name":"Vessa Gorse","mapId":"MORNAY_APOTHECARY_MAP","role":"herb sorter","category":"worker","x":2.5,"y":3.5,"spriteType":"worker","text":"The dry spell changed what the collectors brought in. Melva tests each batch before we use it. A familiar leaf from stressed ground isn't a promise of familiar strength.","facing":"up"}),
  Object.freeze({"id":"mornay_nerrin_hale","name":"Nerrin Hale","mapId":"MORNAY_APOTHECARY_MAP","role":"sleepless customer","category":"resident_or_visitor","x":10.5,"y":6.5,"spriteType":"patron","text":"The night shift ends when the schoolchildren start passing my window. I know their Mera Dren lesson almost by heart. I would prefer to learn it after sleeping.","facing":"up"}),
  Object.freeze({"id":"mornay_orel_quist","name":"Orel Quist","mapId":"MORNAY_APOTHECARY_MAP","role":"medicine courier","category":"worker","x":12.5,"y":7.5,"spriteType":"worker","text":"Some costly medicines travel by rail in the northeast. These go to the next district in my pack. Melva wraps the glass carefully; I pick my steps just as carefully.","facing":"left"}),
  Object.freeze({"id":"mornay_thelin_vole","name":"Thelin Vole","mapId":"MORNAY_APOTHECARY_MAP","role":"carpenter buying salve","category":"worker","x":5.5,"y":6.5,"spriteType":"worker","text":"I mend the dry walkways people use through the fen. One splinter and I am here buying salve. Hesta sold me good gloves. I had taken them off.","facing":"left"}),
  Object.freeze({"id":"mornay_rissa_yew","name":"Rissa Yew","mapId":"MORNAY_SOUTH_ROWS_UNIT_1_MAP","role":"caregiver","category":"worker","x":6.5,"y":7.5,"spriteType":"worker","text":"My mother thinks a bitter medicine must be doing more. I read Melva's directions aloud anyway. We have agreed the label gets a vote, even in her own house.","facing":"left"}),
  Object.freeze({"id":"mornay_dannet_pate","name":"Dannet Pate","mapId":"MORNAY_APOTHECARY_MAP","role":"bottle washer","category":"worker","x":3.5,"y":10.5,"spriteType":"worker","text":"Plain water isn't always clean water. Melva taught me that before she trusted me with a bottle. Now I spend half my time washing and the other half refusing to hurry it.","facing":"left"}),
  Object.freeze({"id":"mornay_hesta_sorn","name":"Hesta Sorn","mapId":"MORNAY_WORKGEAR_MAP","role":"workgear keeper","category":"merchant","x":4.5,"y":4.5,"spriteType":"patron","text":"Working knives, road arms and gear we can repair. Try both boots. Your employer's promise to replace them is not payment.","service":"workgear","facing":"down"}),
  Object.freeze({"id":"mornay_morren_flint","name":"Morren Flint","mapId":"MORNAY_WORKGEAR_MAP","role":"fitter","category":"worker","x":11.5,"y":3.5,"spriteType":"worker","text":"A removal crew bought belts here last week. They asked about spare straps before asking about polish. I find that reassuring in people who mean to go back out into the fen.","facing":"down"}),
  Object.freeze({"id":"mornay_isa_marrin","name":"Isa Marrin","mapId":"MORNAY_WORKGEAR_MAP","role":"leatherworker","category":"worker","x":12.5,"y":8.5,"spriteType":"worker","text":"Jessa does the cart harness; I do belts and pack straps. We exchange scraps. Good leather costs too much to throw away because a piece is an awkward shape.","facing":"down"}),
  Object.freeze({"id":"mornay_fenris_roy","name":"Fenris Roy","mapId":"MORNAY_WORKGEAR_MAP","role":"dock recruit","category":"worker","x":4.5,"y":7.5,"spriteType":"worker","text":"Gessa said gloves, sound boots and no loose sleeves. The men outside offered several more expensive opinions. I think I will start with the woman who runs the shift.","facing":"up"}),
  Object.freeze({"id":"mornay_galda_thorn","name":"Galda Thorn","mapId":"MORNAY_WORKGEAR_MAP","role":"survey worker","category":"worker","x":10.5,"y":7.5,"spriteType":"worker","text":"Ketta needs the bank measured where the mud pulls your boots off. A new pair isn't a luxury if the old soles stay behind. Try explaining that on an expense form.","facing":"right"}),
  Object.freeze({"id":"mornay_perren_croft","name":"Perren Croft","mapId":"MORNAY_WORKGEAR_MAP","role":"repair customer","category":"resident_or_visitor","x":11.5,"y":11.5,"spriteType":"patron","text":"These boots survived three seasons on the canal banks. The cloth inside went first. Hesta repaired that instead of selling me a whole new pair; I came back for a reason.","facing":"up"}),
  Object.freeze({"id":"mornay_lorna_wark","name":"Lorna Wark","mapId":"MORNAY_WORKGEAR_MAP","role":"counter assistant","category":"worker","x":6.5,"y":4.5,"spriteType":"worker","text":"Sizes are on the shelf edge, not the shelf you wish were yours.","facing":"left"}),
  Object.freeze({"id":"mornay_dessin_bellows","name":"Dessin Bellows","mapId":"MORNAY_WORKGEAR_MAP","role":"pack stitcher","category":"worker","x":3.5,"y":10.5,"spriteType":"worker","text":"I stitched a hidden pocket for a courier's sealed papers. He wanted it dry, not secret. That is a harder promise on the fen road.","facing":"left"}),
  Object.freeze({"id":"mornay_hal_venn","name":"Hal Venn","mapId":"MORNAY_CHANDLER_MAP","role":"chandler and secondhand dealer","category":"merchant","x":11.5,"y":4.5,"spriteType":"patron","text":"We sell outright and buy outright. Jarven keeps the public book. I will not name a seller because someone in a good coat asks. The object is what I value.","network":"logistics associate","service":"chandler","facing":"down"}),
  Object.freeze({"id":"mornay_elsra_firth","name":"Elsra Firth","mapId":"MORNAY_CHANDLER_MAP","role":"chandler's assistant","category":"merchant","x":13.5,"y":3.5,"spriteType":"worker","text":"A lake boat wants rope, wick and spare fittings. A visitor asks why we don't get a railway. I ask which of those a railway would deliver to a boat in a squall.","facing":"up"}),
  Object.freeze({"id":"mornay_jarven_clay","name":"Jarven Clay","mapId":"MORNAY_CHANDLER_MAP","role":"secondhand clerk","category":"resident_or_visitor","x":12.5,"y":10.5,"spriteType":"clerk","text":"No pledges for later redemption. An outright sale at the usual secondhand rate. Keep anything you cannot afford to lose.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_nessa_corst","name":"Nessa Corst","mapId":"MORNAY_CHANDLER_MAP","role":"sailor buying tools","category":"worker","x":10.5,"y":7.5,"spriteType":"worker","text":"I sold my tools when the crew was laid off. The drought has made us all very careful about cargo weight, except the rent man. These will have to earn their price again.","facing":"up"}),
  Object.freeze({"id":"mornay_veldin_greaves","name":"Veldin Greaves","mapId":"MORNAY_CHANDLER_MAP","role":"mate buying supplies","category":"worker","x":5.5,"y":4.5,"spriteType":"worker","text":"Oil, wick, a spare sounding line. Captain says we know the Drynport run. I would like the water to know it too before we stop checking.","facing":"left"}),
  Object.freeze({"id":"mornay_brissa_tern","name":"Brissa Tern","mapId":"MORNAY_CHANDLER_MAP","role":"resident selling plate","category":"resident_or_visitor","x":10.5,"y":10.5,"spriteType":"patron","text":"The plate came from my mother's wedding table. I'd rather keep it. I'd also rather pay the rent before the landlord starts coming round when the children are home.","facing":"right"}),
  Object.freeze({"id":"mornay_otrin_dain","name":"Otrin Dain","mapId":"MORNAY_CHANDLER_MAP","role":"repairer examining purchase","category":"worker","x":3.5,"y":5.5,"spriteType":"worker","text":"Stonehaven steel, if the old mark is honest. I'll judge the edge before paying for the name. There's useful work left in it either way.","facing":"down"}),
  Object.freeze({"id":"mornay_fennra_rill","name":"Fennra Rill","mapId":"MORNAY_CHANDLER_MAP","role":"candle maker","category":"worker","x":4.5,"y":9.5,"spriteType":"worker","text":"Nerit reads by lamplight; some of his neighbours buy my candle ends. Study costs something even when the examination doesn't. I save the longest pieces for them.","facing":"left"}),
  Object.freeze({"id":"mornay_rella_wold","name":"Rella Wold","mapId":"MORNAY_GATE_INN_MAP","role":"gate innkeeper and cook","category":"service","x":2.5,"y":3.5,"spriteType":"patron","text":"Sima is on errands. Thirty gold for the party to rest. Shared rooms upstairs; keep your boots off the blankets.","service":"gate_inn","facing":"down"}),
  Object.freeze({"id":"mornay_benric_cove","name":"Benric Cove","mapId":"MORNAY_GATE_INN_MAP","role":"serving worker","category":"service","x":6.5,"y":5.5,"spriteType":"worker","text":"Dayoff brings half the ward in to talk. The crews still change shifts and the bowls still need washing. Rella gives us our rest in turns when the rush is over.","facing":"left"}),
  Object.freeze({"id":"mornay_delsa_quill","name":"Delsa Quill","mapId":"MORNAY_GATE_INN_MAP","role":"card player","category":"worker","x":3.5,"y":7.5,"spriteType":"worker","text":"The collection paid for food, not revenge. Some young fool proposed breaking a contractor's windows. Whose wages would replace the glass?","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_torva_brin","name":"Torva Brin","mapId":"MORNAY_GATE_INN_MAP","role":"merchant's clerk","category":"resident_or_visitor","x":10.5,"y":4.5,"spriteType":"clerk","text":"My employer travels with a Kethrin letter of credit. I carry enough gold for meals and keep every receipt. His paper opens accounts; mine explains why I ate supper.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_issen_dorr","name":"Issen Dorr","mapId":"MORNAY_GATE_INN_MAP","role":"roads worker","category":"worker","x":5.5,"y":7.5,"spriteType":"worker","text":"The causeway notices still say temporary. I've repaired enough road to know wet ground is difficult. I'd like the officials renewing the notice to spend a morning out there with us.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_pelda_wren","name":"Pelda Wren","mapId":"MORNAY_GATE_INN_MAP","role":"traveller","category":"resident_or_visitor","x":12.5,"y":9.5,"spriteType":"traveler","text":"I asked for an ordinary inn. Rella found me a bed and someone showed me where the water was. After the fen road, being left in peace feels remarkably kind.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_orven_lume","name":"Orven Lume","mapId":"MORNAY_GATE_INN_MAP","role":"potter visiting market","category":"worker","x":2.5,"y":11.5,"spriteType":"worker","text":"Oren orders sturdy cups for the school. I bring a few extra; children happen. He pays for the order and returns the sound ones nobody needed.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_hessa_vane","name":"Hessa Vane","mapId":"MORNAY_PATE_HOME_MAP","role":"local regular","category":"worker","x":5.5,"y":7.5,"spriteType":"worker","text":"We used to watch river wrestling on Dayoff. Drenwick takes its holds and breaks seriously. I prefer a clean bout and somewhere warm afterward.","facing":"left"}),
  Object.freeze({"id":"mornay_vannic_nair","name":"Vannic Nair","mapId":"MORNAY_GATE_INN_MAP","role":"off-duty watch","category":"official","x":10.5,"y":9.5,"spriteType":"clerk","text":"Off duty. If somebody calls the washer a Reclaimer again, they can make the complaint in writing tomorrow. Tonight she is bringing clean linen.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_senric_teel","name":"Senric Teel","mapId":"MORNAY_GATE_INN_MAP","role":"kitchen boy","category":"service","x":4.5,"y":3.5,"spriteType":"child","text":"Marla taught me the chorus of that Jontek song. Rella says I may sing after I carry the soup. Apparently dancing while carrying it is not a useful new skill.","facing":"up"}),
  Object.freeze({"id":"mornay_marla_fallow","name":"Marla Fallow","mapId":"MORNAY_GATE_INN_MAP","role":"itinerant singer","category":"worker","x":12.5,"y":6.5,"spriteType":"worker","text":"I know the Jontek tune. Everybody knows the Jontek tune. If one person asks for an old canal song, I shall sing it with unreasonable gratitude.","facing":"left"}),
  Object.freeze({"id":"mornay_elva_brack","name":"Elva Brack","mapId":"MORNAY_DOCK_STEPS_UNIT_2_MAP","role":"sailor's mother","category":"resident_or_visitor","x":6.5,"y":9.5,"spriteType":"patron","text":"He sends money from Drynport when the crew is paid. I ask Oswen to write back about the kitchen and the neighbours. I want him to have a little of home, not just another bill.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_farren_moss","name":"Farren Moss","mapId":"MORNAY_GATE_BEDS_MAP","role":"travelling clerk","category":"resident_or_visitor","x":3.5,"y":4.5,"spriteType":"clerk","text":"I passed the accounts examination and took the first vacancy. It was nowhere near home. They were quite right that Imperial service would let me see more of the province.","facing":"left"}),
  Object.freeze({"id":"mornay_idda_fane","name":"Idda Fane","mapId":"MORNAY_GATE_BEDS_MAP","role":"farm visitor","category":"resident_or_visitor","x":5.5,"y":4.5,"spriteType":"traveler","text":"At home we stop when the weather lets us. Here they call the fifth day Dayoff and make plans. I like that. I would like to make a plan that survives the weather.","facing":"left"}),
  Object.freeze({"id":"mornay_ossen_mote","name":"Ossen Mote","mapId":"MORNAY_GATE_BEDS_MAP","role":"seasonal labourer","category":"worker","x":12.5,"y":4.5,"spriteType":"worker","text":"I cut reeds until the contractor stopped taking bundles. Berrit's yard may need hands tomorrow. My bed is the one with everything I own underneath; I keep it ready to move.","facing":"left"}),
  Object.freeze({"id":"mornay_velra_hume","name":"Velra Hume","mapId":"MORNAY_GATE_BEDS_MAP","role":"visiting seamworker","category":"worker","x":13.5,"y":6.5,"spriteType":"worker","text":"I brought a spare dress and have mended everybody else's. Rella put a meal aside for me. That wasn't the arrangement, but I was glad of it.","facing":"down"}),
  Object.freeze({"id":"mornay_jalin_reed","name":"Jalin Reed","mapId":"MORNAY_GATE_BEDS_MAP","role":"pack trader","category":"worker","x":3.5,"y":9.5,"spriteType":"worker","text":"A dealer offered me cheap imitation Bracelets. Said people would buy the promise even if the work was poor. I carry needles and buttons. They do what I say they do.","facing":"left"}),
  Object.freeze({"id":"mornay_nesset_yarrow","name":"Nesset Yarrow","mapId":"MORNAY_GATE_BEDS_MAP","role":"boat passenger","category":"resident_or_visitor","x":5.5,"y":9.5,"spriteType":"traveler","text":"I came off the lake crossing wet to the knees. Rella found dry socks and asked no questions until I'd eaten. I shall remember Mornay rather better for that.","facing":"left"}),
  Object.freeze({"id":"mornay_brelna_ashe","name":"Brelna Ashe","mapId":"MORNAY_GATE_BEDS_MAP","role":"student applicant","category":"resident_or_visitor","x":10.5,"y":9.5,"spriteType":"patron","text":"I can pass the Collegium's reading exercises. Father can pay for the journey here. We haven't yet found anyone who treats those two facts as enough for a place.","facing":"right"}),
  Object.freeze({"id":"mornay_corra_purl","name":"Corra Purl","mapId":"MORNAY_GATE_BEDS_MAP","role":"housekeeper","category":"service","x":12.5,"y":11.5,"spriteType":"patron","text":"A shared room still contains private belongings. Kindly remember that.","facing":"up"}),
  Object.freeze({"id":"mornay_gerta_vell","name":"Gerta Vell","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"commercial innkeeper","category":"service","x":11.5,"y":3.5,"spriteType":"patron","text":"Forty gold for the party to rest at the Ledger House. Quiet rooms upstairs. We have commercial guests who need their sleep.","service":"commercial_inn","facing":"down"}),
  Object.freeze({"id":"mornay_odrin_vale","name":"Odrin Vale","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"cook","category":"worker","x":13.5,"y":2.5,"spriteType":"worker","text":"Good honey, fruit, a little patience. That's the pudding. The guest who wanted northern sugar asked for a second helping before remembering to complain.","facing":"right"}),
  Object.freeze({"id":"mornay_lessa_crowe","name":"Lessa Crowe","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"server","category":"service","x":9.5,"y":6.5,"spriteType":"worker","text":"The passengers argue about which capital is grander. Lumina for beauty, Halcyra for importance. Neither party has yet noticed who brought their supper.","facing":"left"}),
  Object.freeze({"id":"mornay_harnet_brill","name":"Harnet Brill","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"lake skipper","category":"resident_or_visitor","x":2.5,"y":4.5,"spriteType":"traveler","text":"A passenger called the Valmere a big pond. We passed the headland and took water over the bow for an hour. He calls it the inland sea now. The water hasn't changed its opinion of him.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_nessa_wren","name":"Nessa Wren","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"deckhand","category":"resident_or_visitor","x":4.5,"y":4.5,"spriteType":"traveler","text":"They wrestle in moving water at Drenwick. On this lake I spend my wages trying to stay out of it. I'll watch a bout from the bank, thanks.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_elda_wick","name":"Elda Wick","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"sailmaker","category":"worker","x":3.5,"y":9.5,"spriteType":"worker","text":"Three crews asked for sail repairs on credit. Tobin and I share the small jobs so both workshops keep going. Trust matters. So does having enough gold to buy the thread.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_corvinna_dale","name":"Corvinna Dale","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"cargo passenger","category":"resident_or_visitor","x":10.5,"y":10.5,"spriteType":"traveler","text":"Earlier in the journey, my client took the rail with samples and a contract. I am travelling with the actual cloth. When he asks where I've been, I shall tell him where his profit was waiting.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_pelren_sill","name":"Pelren Sill","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"crew cook","category":"worker","x":12.5,"y":6.5,"spriteType":"worker","text":"No crew to feed until morning. Odrin brought out a bowl and didn't ask me to improve it. It is a pleasure to be somebody else's hungry customer for once.","facing":"down","pose":"seated"}),
  Object.freeze({"id":"mornay_vessa_kest","name":"Vessa Kest","mapId":"MORNAY_SOUTH_ROWS_UNIT_2_MAP","role":"local musician","category":"worker","x":8.5,"y":7.5,"spriteType":"worker","text":"Ansel teaches the notes; I teach his pupils the canal songs their parents request. On Dayoff we manage a whole room between us, provided nobody argues about the verses.","facing":"right"}),
  Object.freeze({"id":"mornay_talric_gant","name":"Talric Gant","mapId":"MORNAY_COMMERCIAL_INN_MAP","role":"off-duty shipping clerk","category":"resident_or_visitor","x":5.5,"y":9.5,"spriteType":"clerk","text":"I copied a Bethany traveller's letter for a shipping client. Terraces, gardens, starflowers shining after sunset. I'd like to see Skybloom someday without somebody dictating the description.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_jorra_vey","name":"Jorra Vey","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"boatswain","category":"worker","x":3.5,"y":4.5,"spriteType":"worker","text":"Wake me for departure. Leave improvements to the world until afterward.","facing":"left"}),
  Object.freeze({"id":"mornay_merdin_shaw","name":"Merdin Shaw","mapId":"MORNAY_DOCK_STEPS_UNIT_2_MAP","role":"deckhand","category":"resident_or_visitor","x":8.5,"y":7.5,"spriteType":"traveler","text":"We practise tying knots. My wages still untie themselves.","facing":"right"}),
  Object.freeze({"id":"mornay_sella_dace","name":"Sella Dace","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"navigator's assistant","category":"worker","x":11.5,"y":4.5,"spriteType":"worker","text":"Drynport's quays change with the water. I mark the soundings before putting the chart away. The old chart isn't lying; it just hasn't been there lately.","facing":"left"}),
  Object.freeze({"id":"mornay_verren_noll","name":"Verren Noll","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"lake crewman","category":"resident_or_visitor","x":13.5,"y":6.5,"spriteType":"traveler","text":"My daughter found Drynport on the school map and traced my crossing with her finger. I wish journeys were that simple. I send a letter whenever I can.","facing":"up"}),
  Object.freeze({"id":"mornay_brinna_beck","name":"Brinna Beck","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"freighter's mate","category":"worker","x":3.5,"y":10.5,"spriteType":"worker","text":"A shallower scow carries less, so a full warehouse doesn't mean full wages for us. People see the cargo waiting and think every crew must be busy.","facing":"up"}),
  Object.freeze({"id":"mornay_hessa_rann","name":"Hessa Rann","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"rope worker travelling home","category":"resident_or_visitor","x":6.5,"y":9.5,"spriteType":"traveler","text":"Essie has kept a place for me at supper. I brought her good thread. If the packet is late, she'll feed everyone else and keep mine warm; she always does.","facing":"left"}),
  Object.freeze({"id":"mornay_torren_linn","name":"Torren Linn","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"cabin attendant","category":"worker","x":12.5,"y":11.5,"spriteType":"worker","text":"I scrub cabins, not navigate them. Nevertheless every passenger who sees a dark cloud asks me whether we shall arrive. I usually say the skipper would like to know too.","facing":"up"}),
  Object.freeze({"id":"mornay_elsven_pike","name":"Elsven Pike","mapId":"MORNAY_COMMERCIAL_BEDS_MAP","role":"crew member writing home","category":"worker","x":12.5,"y":6.5,"spriteType":"worker","text":"I'm writing about the meal, the room, a child waving from the quay. My family knows the lake is dangerous. They deserve to hear something else about my days on it.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_oren_teal","name":"Oren Teal","mapId":"MORNAY_SCHOOL_MAP","role":"headteacher","category":"service","x":4.5,"y":2.5,"spriteType":"clerk","text":"The Empire teaches a child to petition, then charges the parent to have the words copied. I understand why the Reclaimers find listeners. I will not have children carrying their messages.","network":"educated sympathizer","facing":"down"}),
  Object.freeze({"id":"mornay_nelda_quill","name":"Nelda Quill","mapId":"MORNAY_SCHOOL_MAP","role":"school administrator","category":"service","x":13.5,"y":10.5,"spriteType":"clerk","text":"The ward school is publicly funded. Boots and aprons still cost families money. Nessa brings what she can; Oren makes sure a missing apron doesn't become a missing pupil.","facing":"down"}),
  Object.freeze({"id":"mornay_hadria_beck","name":"Hadria Beck","mapId":"MORNAY_SCHOOL_MAP","role":"arithmetic teacher","category":"service","x":6.5,"y":4.5,"spriteType":"clerk","text":"Four workdays, then Dayoff. We count a week's pay and what the household needs. The children notice immediately when I give the example family more mouths than meals.","facing":"down"}),
  Object.freeze({"id":"mornay_serren_crowe","name":"Serren Crowe","mapId":"MORNAY_SCHOOL_MAP","role":"reading teacher","category":"service","x":11.5,"y":4.5,"spriteType":"clerk","text":"We read Mera Dren's petition and practise writing our own. The lesson is useful even if the official picture leaves everyone who helped her outside the frame.","facing":"left"}),
  Object.freeze({"id":"mornay_tessa_orr","name":"Tessa Orr","mapId":"MORNAY_SCHOOL_MAP","role":"classroom helper","category":"service","x":1.5,"y":8.5,"spriteType":"worker","text":"A parent can choose whether to send a child to school. Some need help with work at home. I keep the missed reading ready; I would rather they came back than felt ashamed.","facing":"right"}),
  Object.freeze({"id":"mornay_perrin_mere","name":"Perrin Mere","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":3.5,"y":7.5,"spriteType":"child","text":"Aunt Dena says counting your pay is arithmetic you should practise.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_vella_corst","name":"Vella Corst","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":6.5,"y":7.5,"spriteType":"child","text":"Father says his boat is important even if it isn't on the big map. I told him Calwick isn't important enough for that map either. He said that was not helping.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_ivenna_sorn","name":"Ivenna Sorn","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":10.5,"y":7.5,"spriteType":"child","text":"Mera got the road moved thirty paces. I wrote thirteen by mistake. Hadria asked whether the village would still reach its water. I went back and checked.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_dorrie_firth","name":"Dorrie Firth","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":3.5,"y":10.5,"spriteType":"child","text":"The book says 'Be a Mera'. Mother says start by putting my complaint about my brother in writing. I need another sheet.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_helren_pate","name":"Helren Pate","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":6.5,"y":10.5,"spriteType":"child","text":"Fort Ariel grows strawberries inside a warm circle in the polar cold. The book says nobody knows how she did it. I like a book that admits it doesn't know something.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_maris_glyn","name":"Maris Glyn","mapId":"MORNAY_SCHOOL_MAP","role":"pupil","category":"resident_or_visitor","x":13.5,"y":8.5,"spriteType":"child","text":"I read the Mera Dren story to my little brother. He wants the engineer in the picture too. Father says that's the first sensible complaint we've had all week.","facing":"left","dayOff":{"mapId":"MORNAY_GLYN_HOME_MAP","x":5.5,"y":7.5,"facing":"left","pose":null}}),
  Object.freeze({"id":"mornay_bessa_rook","name":"Bessa Rook","mapId":"MORNAY_SCHOOL_MAP","role":"parent","category":"resident_or_visitor","x":12.5,"y":12.5,"spriteType":"patron","text":"We can manage the ward school. The Collegium wants fees and preparation. My daughter asks what happens if she is clever enough but we are not rich enough.","facing":"left"}),
  Object.freeze({"id":"mornay_ellin_hesk","name":"Ellin Hesk","mapId":"MORNAY_SCHOOL_MAP","role":"caretaker","category":"service","x":13.5,"y":5.5,"spriteType":"worker","text":"I learnt my letters late. These children have a place to learn before they start hauling and mending. I keep the roof sound; that is my part of the Education Act.","facing":"up"}),
  Object.freeze({"id":"mornay_verra_moss","name":"Verra Moss","mapId":"MORNAY_SCHOOL_MAP","role":"adult learner","category":"worker","x":10.5,"y":10.5,"spriteType":"worker","text":"I can read the levy notice myself now. I don't agree with it, but I know what it actually says. Oren says that's a better place to start an argument.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_edrin_saye","name":"Edrin Saye","mapId":"MORNAY_HARBOUR_MAP","role":"customs assessor","category":"official","x":2.5,"y":2.5,"spriteType":"clerk","text":"The Reclaimers use real grievances. That does not make every unlisted crate harmless. If Voss wants a cargo inquiry, she can send a signed request. We will not own her speculation.","facing":"down"}),
  Object.freeze({"id":"mornay_maura_dell","name":"Maura Dell","mapId":"MORNAY_HARBOUR_MAP","role":"harbour administrator","category":"official","x":11.5,"y":2.5,"spriteType":"clerk","text":"Berth allocation here. Excise with Saye. Unsafe shore works with Arlis at the IJC office. Please do not bring their unanswered forms back to my counter.","facing":"down"}),
  Object.freeze({"id":"mornay_hassel_muir","name":"Hassel Muir","mapId":"MORNAY_HARBOUR_MAP","role":"manifest clerk","category":"official","x":5.5,"y":2.5,"spriteType":"clerk","text":"Write Thornmere if that's where the cargo started, not just Valmere province. A tax heading and a lake are different sorts of place. The next clerk needs to know which you mean.","facing":"down"}),
  Object.freeze({"id":"mornay_vessa_fenn","name":"Vessa Fenn","mapId":"MORNAY_HARBOUR_MAP","role":"fee clerk","category":"official","x":3.5,"y":6.5,"spriteType":"clerk","text":"Small consignments pay the minimum charge. Large ones spread it across more cargo. I did not write the schedule and cannot waive it.","facing":"down"}),
  Object.freeze({"id":"mornay_orris_teel","name":"Orris Teel","mapId":"MORNAY_HARBOUR_MAP","role":"berth scheduler","category":"official","x":10.5,"y":6.5,"spriteType":"worker","text":"Drynport sends a departure estimate; Lowen writes it down as an arrival promise. Then two captains want the same water. I leave room in the schedule for weather. He calls it wasted space.","facing":"down"}),
  Object.freeze({"id":"mornay_dalen_wist","name":"Dalen Wist","mapId":"MORNAY_HARBOUR_MAP","role":"inspection officer","category":"official","x":13.5,"y":6.5,"spriteType":"clerk","text":"A damaged hoist deserves an inspection whether the owner is well connected or not. Gessa has asked twice. I have kept both requests; someone may eventually want the dates.","facing":"down"}),
  Object.freeze({"id":"mornay_berra_yule","name":"Berra Yule","mapId":"MORNAY_HARBOUR_MAP","role":"customs copyist","category":"official","x":4.5,"y":11.5,"spriteType":"worker","text":"Initial the correction here. I'll show you which box, but I can't sign it for you. People are afraid a small mistake will cost another journey. Sometimes they are right.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_neven_brume","name":"Neven Brume","mapId":"MORNAY_HARBOUR_MAP","role":"harbour messenger","category":"official","x":6.5,"y":9.5,"spriteType":"worker","text":"The scheduled packet waits over Dayoff. My legs don't. If Maura needs a reply from the quay before morning, she sends me with it.","facing":"left"}),
  Object.freeze({"id":"mornay_tilda_vole","name":"Tilda Vole","mapId":"MORNAY_HARBOUR_MAP","role":"waiting agent","category":"worker","x":2.5,"y":9.5,"spriteType":"worker","text":"A Kethrin credit letter doesn't unload a barge. My client finds that surprising every time. I have asked him to pay the waiting crew before writing another complaint.","facing":"up"}),
  Object.freeze({"id":"mornay_harnis_roy","name":"Harnis Roy","mapId":"MORNAY_HARBOUR_MAP","role":"barge master","category":"worker","x":9.5,"y":9.5,"spriteType":"worker","text":"I paid a broker for quick clearance. He knew which clerk was away before the harbour did. I am beginning to understand what I bought.","facing":"up"}),
  Object.freeze({"id":"mornay_elna_stern","name":"Elna Stern","mapId":"MORNAY_HARBOUR_MAP","role":"small trader","category":"worker","x":12.5,"y":10.5,"spriteType":"worker","text":"One little consignment of reed mats. The minimum charge takes more of my profit than a full boat's owner loses. Vessa understands the sum; she still has to collect it.","facing":"left"}),
  Object.freeze({"id":"mornay_corren_wark","name":"Corren Wark","mapId":"MORNAY_HARBOUR_MAP","role":"archive clerk","category":"official","x":14.5,"y":4.5,"spriteType":"clerk","text":"The freight books show where scows used to load fully. Now captains come in to argue with the old figures. I give them copies. They should have something better than memory to work from.","facing":"up"}),
  Object.freeze({"id":"mornay_delsin_orl","name":"Delsin Orl","mapId":"MORNAY_HARBOUR_MAP","role":"inspection assistant","category":"official","x":12.5,"y":8.5,"spriteType":"worker","text":"I sat the internal examination after years of counting boxes. My supervisor noticed I could do the sums. I try to notice when the newer hands can do more than they're paid for.","facing":"up"}),
  Object.freeze({"id":"mornay_rissa_dane","name":"Rissa Dane","mapId":"MORNAY_HARBOUR_MAP","role":"vessel owner","category":"worker","x":5.5,"y":5.5,"spriteType":"worker","text":"I paid for a sound hull and a careful skipper. Mrs Vale says I could have bought a cheaper boat. Perhaps. I prefer to hear the crew complain about me in person.","facing":"up"}),
  Object.freeze({"id":"mornay_varda_fen","name":"Varda Fen","mapId":"MORNAY_WAREHOUSE_MAP","role":"warehouse supervisor","category":"worker","x":12.5,"y":4.5,"spriteType":"worker","text":"Bram catches missing sacks. I catch the arguments. The bonded annex is locked. Work in the public store does not authorize you beyond that door.","facing":"down"}),
  Object.freeze({"id":"mornay_helric_tress","name":"Helric Tress","mapId":"MORNAY_WAREHOUSE_MAP","role":"hoist operator","category":"worker","x":6.5,"y":3.5,"spriteType":"worker","text":"Gessa's signal means stop, even with a load hanging. Nevin is in the infirmary because someone wanted one more lift. No cargo is worth another man going there.","facing":"left"}),
  Object.freeze({"id":"mornay_istra_wick","name":"Istra Wick","mapId":"MORNAY_WAREHOUSE_MAP","role":"packing lead","category":"worker","x":4.5,"y":5.5,"spriteType":"worker","text":"Reed padding under the jars, heavy sacks below the light goods. We are sending this through two transfers before it leaves the fen channel. Pack for every pair of hands, not just ours.","facing":"up"}),
  Object.freeze({"id":"mornay_polren_hale","name":"Polren Hale","mapId":"MORNAY_WAREHOUSE_MAP","role":"salt porter","category":"worker","x":2.5,"y":6.5,"spriteType":"worker","text":"The fish needs salt and somebody has to bring it in. Plenty of water in the Valmere, no salt to take from it. The smokers wait for these sacks just as we wait for our pay.","facing":"down"}),
  Object.freeze({"id":"mornay_gessa_noll","name":"Gessa Noll","mapId":"MORNAY_WAREHOUSE_MAP","role":"grain checker","category":"worker","x":11.5,"y":3.5,"spriteType":"worker","text":"A merchant described the rich Lume floodplain to me while I checked his grain. I said rich grain still spoils if he leaves it in a wet sack. He let me finish checking.","facing":"up"}),
  Object.freeze({"id":"mornay_merrit_dace","name":"Merrit Dace","mapId":"MORNAY_WAREHOUSE_MAP","role":"freight scribe","category":"worker","x":13.5,"y":6.5,"spriteType":"worker","text":"I write down what passes the door. Bram keeps his own count. Two records are useful when somebody decides a missing sack must have been a careless labourer's fault.","facing":"left"}),
  Object.freeze({"id":"mornay_arla_rill","name":"Arla Rill","mapId":"MORNAY_WAREHOUSE_MAP","role":"crate assembler","category":"worker","x":5.5,"y":11.5,"spriteType":"worker","text":"The merchant took the quick road. His goods will go by water, as heavy things usually do. I build the crate for the journey the goods get, not the one he remembers.","facing":"left"}),
  Object.freeze({"id":"mornay_oden_gant","name":"Oden Gant","mapId":"MORNAY_DOCK_STEPS_UNIT_3_MAP","role":"night porter","category":"worker","x":10.5,"y":8.5,"spriteType":"worker","text":"People carry folded papers through a warehouse as well as sacks. No label tells you which will get a man dismissed. Ask the day clerk about cargo.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_nessa_muir","name":"Nessa Muir","mapId":"MORNAY_WAREHOUSE_MAP","role":"meal runner","category":"worker","x":9.5,"y":7.5,"spriteType":"worker","text":"Vela sends Kelda's bowl first. I bring it while the yard is eating so she has company. Losing a shift shouldn't mean losing the people you used to work beside.","facing":"right"}),
  Object.freeze({"id":"mornay_verdin_clay","name":"Verdin Clay","mapId":"MORNAY_WAREHOUSE_MAP","role":"warehouse sweeper","category":"worker","x":6.5,"y":11.5,"spriteType":"worker","text":"Lost grain feeds something. I prefer it not live here.","facing":"up"}),
  Object.freeze({"id":"mornay_lerna_brack","name":"Lerna Brack","mapId":"MORNAY_WAREHOUSE_MAP","role":"damaged-goods clerk","category":"resident_or_visitor","x":13.5,"y":10.5,"spriteType":"clerk","text":"Wet before loading or wet in our store? It matters to the claim. I ask the porter who carried it, though his name isn't printed on the expensive paperwork.","facing":"left"}),
  Object.freeze({"id":"mornay_fenna_crowe","name":"Fenna Crowe","mapId":"MORNAY_WAREHOUSE_MAP","role":"new packer","category":"worker","x":10.5,"y":9.5,"spriteType":"worker","text":"I could read the labels before I got here. Istra showed me which damaged corners to look for. School and a patient workmate have kept me from making two different sorts of mistake.","facing":"right"}),
  Object.freeze({"id":"mornay_halden_rusk","name":"Halden Rusk","mapId":"MORNAY_WORKSHOP_MAP","role":"printer","category":"worker","x":2.5,"y":2.5,"spriteType":"worker","text":"My nephew Tavi sets the type. I have refused work from officials and from their enemies. A threat does not become an argument because it arrives with a petition.","facing":"down"}),
  Object.freeze({"id":"mornay_irma_bellows","name":"Irma Bellows","mapId":"MORNAY_WORKSHOP_MAP","role":"toolmaker","category":"worker","x":11.5,"y":2.5,"spriteType":"worker","text":"I make a handle to fit the hand. A man with an old injury may need a different grip, not a different trade. Selven sent someone over to try one last week.","facing":"down"}),
  Object.freeze({"id":"mornay_cerren_flint","name":"Cerren Flint","mapId":"MORNAY_WORKSHOP_MAP","role":"smith","category":"worker","x":13.5,"y":3.5,"spriteType":"worker","text":"Stonehaven makes fine metalwork. I still test a secondhand blade before trusting the mark. Hal understands; he'd rather I found a flaw here than a customer found it on the road.","facing":"up"}),
  Object.freeze({"id":"mornay_vesta_dorr","name":"Vesta Dorr","mapId":"MORNAY_WORKSHOP_MAP","role":"printer's reader","category":"worker","x":3.5,"y":4.5,"spriteType":"worker","text":"Pella's sheets were seized before anyone read them. That pleased the man selling blank forms next door. He has doubled his prices.","facing":"up"}),
  Object.freeze({"id":"mornay_pelda_gorse","name":"Pelda Gorse","mapId":"MORNAY_WORKSHOP_MAP","role":"paper cutter","category":"worker","x":4.5,"y":6.5,"spriteType":"worker","text":"I keep the paper offcuts for Oren's reading class. There's room for a few words on almost anything. Tavi leaves them blank on both sides when he can.","facing":"down"}),
  Object.freeze({"id":"mornay_jerrin_cole","name":"Jerrin Cole","mapId":"MORNAY_WORKSHOP_MAP","role":"repair apprentice","category":"worker","x":12.5,"y":7.5,"spriteType":"worker","text":"Torlin let me fit a spoke, then made me explain how the wheel would take the weight. I hoped he'd just tell me it looked good. I understand why he didn't.","facing":"down"}),
  Object.freeze({"id":"mornay_hessa_yarrow","name":"Hessa Yarrow","mapId":"MORNAY_WORKSHOP_MAP","role":"sailcloth stitcher","category":"worker","x":5.5,"y":8.5,"spriteType":"worker","text":"Tobin marks the worn places; I stitch the reinforcement. We leave the sound cloth alone. A crew buying repairs deserves more than an impressive patch over the wrong tear.","facing":"up","pose":"seated"}),
  Object.freeze({"id":"mornay_torlin_hesk","name":"Torlin Hesk","mapId":"MORNAY_WORKSHOP_MAP","role":"wheelwright","category":"worker","x":10.5,"y":10.5,"spriteType":"worker","text":"Helven wants his spare wheel before the freight clears. I told him a rushed wheel can scatter a whole day's wages across the road. He is waiting, though not quietly.","facing":"right"}),
  Object.freeze({"id":"mornay_nilda_linnet","name":"Nilda Linnet","mapId":"MORNAY_WORKSHOP_MAP","role":"pattern drafter","category":"worker","x":5.5,"y":6.5,"spriteType":"worker","text":"The Collegium ordered cloth cut to a precise pattern. Essie's customers bring a child's old coat and ask how much room I can leave for growing. Both take care; only one impresses people.","facing":"down"}),
  Object.freeze({"id":"mornay_orsa_purl","name":"Orsa Purl","mapId":"MORNAY_WORKSHOP_MAP","role":"workshop bookkeeper","category":"resident_or_visitor","x":3.5,"y":11.5,"spriteType":"patron","text":"Gold paid, timber bought, hours worked. I keep all three. When a customer disputes a repair, I want the apprentice's time on the page as plainly as the master's name.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_nessa_quill","name":"Nessa Quill","mapId":"MORNAY_LAUNDRY_MAP","role":"laundry organiser","category":"worker","x":4.5,"y":8.5,"spriteType":"worker","text":"A person can work all week and still need a neighbour. We collect for supper and rent. Anyone demanding names before giving a coin can keep the coin.","network":"confirmed member","facing":"left"}),
  Object.freeze({"id":"mornay_yelda_mere","name":"Yelda Mere","mapId":"MORNAY_LAUNDRY_MAP","role":"washer","category":"worker","x":2.5,"y":4.5,"spriteType":"worker","text":"Dena wants the next meeting about the hoist and unpaid shifts. Others want speeches about bringing everything down. We still have washing to finish afterward.","facing":"up"}),
  Object.freeze({"id":"mornay_cossa_beck","name":"Cossa Beck","mapId":"MORNAY_LAUNDRY_MAP","role":"mender","category":"worker","x":3.5,"y":7.5,"spriteType":"worker","text":"A school apron, a dock coat, Mrs Vale's table linen. I mend the same sort of tear in all three. People are less different at the elbows than they think.","facing":"down","pose":"seated"}),
  Object.freeze({"id":"mornay_brinna_mote","name":"Brinna Mote","mapId":"MORNAY_DOCK_STEPS_UNIT_3_MAP","role":"laundry customer","category":"resident_or_visitor","x":6.5,"y":7.5,"spriteType":"patron","text":"My employer calls the collection a conspiracy. He sent his own porter to ask for food after cutting the man's hours.","facing":"left"}),
  Object.freeze({"id":"mornay_terenna_vane","name":"Terenna Vane","mapId":"MORNAY_LAUNDRY_MAP","role":"wringer operator","category":"worker","x":11.5,"y":3.5,"spriteType":"worker","text":"The rollers take the water out; somebody still has to fetch it in. Jessa and I change places before our hands give out. Dry weather hasn't made washing any lighter.","facing":"down"}),
  Object.freeze({"id":"mornay_jessa_reed","name":"Jessa Reed","mapId":"MORNAY_LAUNDRY_MAP","role":"washer's assistant","category":"worker","x":4.5,"y":4.5,"spriteType":"worker","text":"Yara needs plain sheets, the inns want them all back at once, and our own washing waits. Nessa puts a household bundle through between orders when she can.","facing":"up"}),
  Object.freeze({"id":"mornay_fenric_orr","name":"Fenric Orr","mapId":"MORNAY_LAUNDRY_MAP","role":"infirmary laundry carrier","category":"worker","x":11.5,"y":9.5,"spriteType":"worker","text":"Yara asks for the plain sheets first. Nessa sends them whether the last bill was paid or not. Neither of them has time to argue about credit for it.","facing":"right"}),
  Object.freeze({"id":"mornay_orlin_bale","name":"Orlin Bale","mapId":"MORNAY_LAUNDRY_MAP","role":"neighbour awaiting wash","category":"worker","x":6.5,"y":10.5,"spriteType":"worker","text":"I offered to help. They found an alarming amount of help for me.","facing":"left"}),
  Object.freeze({"id":"mornay_della_hume","name":"Della Hume","mapId":"MORNAY_BOARDING_MAP","role":"boardinghouse keeper","category":"service","x":4.5,"y":9.5,"spriteType":"patron","text":"Rent includes a bed. It does not include finding work. The hiring board is at the East Gate; do not give a stranger your last coin for a place in line.","facing":"right"}),
  Object.freeze({"id":"mornay_hesten_vale","name":"Hesten Vale","mapId":"MORNAY_BOARDING_UNIT_1_MAP","role":"seasonal clerk","category":"resident_or_visitor","x":8.5,"y":9.5,"spriteType":"clerk","text":"Temporary clerk, examination passed, still waiting for a permanent appointment. I can recite the Council's Three Elevens. It hasn't made the vacancy list any longer.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_rella_fenner","name":"Rella Fenner","mapId":"MORNAY_BOARDING_UNIT_1_MAP","role":"dock worker","category":"worker","x":6.5,"y":7.5,"spriteType":"worker","text":"The early shift eats quietly. Della leaves space by the stove for us. Dayoff or workday, the boats still need unloading when they reach the quay.","facing":"left"}),
  Object.freeze({"id":"mornay_otrin_wren","name":"Otrin Wren","mapId":"MORNAY_BOARDING_UNIT_2_MAP","role":"unemployed joiner","category":"worker","x":6.5,"y":9.5,"spriteType":"worker","text":"They dismissed a man for organizing. Then the foreman dismissed two men who had never spoken to him. Cheap hands were waiting outside.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_vessa_fallow","name":"Vessa Fallow","mapId":"MORNAY_BOARDING_UNIT_4_MAP","role":"kitchen worker","category":"worker","x":6.5,"y":8.5,"spriteType":"worker","text":"At work I cook for the Ledger House. Downstairs I share a stove with three households. We put one pot on for everyone when the freight pay is late.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_belric_tern","name":"Belric Tern","mapId":"MORNAY_BOARDING_UNIT_3_MAP","role":"retired carrier","category":"resident_or_visitor","x":10.5,"y":8.5,"spriteType":"patron","text":"My wife rests in deep water, away from the boats. Her name is in our family book. The water keeps the body; we keep the name. I like having people here to say it to.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_jorra_yew","name":"Jorra Yew","mapId":"MORNAY_RANN_HOME_MAP","role":"apprentice seamworker","category":"worker","x":9.5,"y":7.5,"spriteType":"worker","text":"Essie pays me for useful work, even while I'm learning. I've put a little aside. Nothing grand planned yet; I'd just like the next decision to be one I can afford.","facing":"right"}),
  Object.freeze({"id":"mornay_marden_sill","name":"Marden Sill","mapId":"MORNAY_BOARDING_UNIT_3_MAP","role":"remittance sender","category":"worker","x":6.5,"y":7.5,"spriteType":"worker","text":"Some men offer quiet passages and cheap carriage. One asked for a fee in the Reclaimers' name. Hal sent him away. I still keep my papers on me.","facing":"left"}),
  Object.freeze({"id":"mornay_selda_brin","name":"Selda Brin","mapId":"MORNAY_COURT_UNIT_1_MAP","role":"parent","category":"resident_or_visitor","x":8.5,"y":9.5,"spriteType":"patron","text":"The Education Act pays for lessons, not for the supper a child could have helped earn. We take turns with the younger ones so the older ones can go. Most days it works.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_harlis_glyn","name":"Harlis Glyn","mapId":"MORNAY_GLYN_HOME_MAP","role":"dockworker","category":"worker","x":9.5,"y":9.5,"spriteType":"worker","text":"Maris read me the Mera Dren lesson, then read the reply to our own complaint. She asked why the office hadn't sent an engineer. I said we'd write again. She fetched the pencil.","facing":"right","pose":"seated"}),
  Object.freeze({"id":"mornay_etta_rook","name":"Etta Rook","mapId":"MORNAY_COURT_UNIT_2_MAP","role":"elder resident","category":"resident_or_visitor","x":6.5,"y":9.5,"spriteType":"patron","text":"Mother dated everything from the Millennial Accord. Before it, after it, the winter we still had the bunting. I remember the mending more clearly than the speeches she described.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_davren_fenwick","name":"Davren Fenwick","mapId":"MORNAY_COURT_MAP","role":"home repairer","category":"worker","x":3.5,"y":10.5,"spriteType":"worker","text":"Everyone under this roof put something toward the repair. Selda kept the names and amounts. We can argue over a missing bowl later; the rain was coming into all our rooms.","facing":"down"}),
  Object.freeze({"id":"mornay_nelva_pike","name":"Nelva Pike","mapId":"MORNAY_COURT_UNIT_4_MAP","role":"fish seller's sister","category":"merchant","x":8.5,"y":10.5,"spriteType":"patron","text":"Niva brings the fish she couldn't sell. I cook enough for Verna too. She sends the dish back clean, usually with something mended folded inside it.","facing":"right"}),
  Object.freeze({"id":"mornay_ossa_nair","name":"Ossa Nair","mapId":"MORNAY_COURT_UNIT_3_MAP","role":"constable's parent","category":"official","x":10.5,"y":8.5,"spriteType":"clerk","text":"Jessa learned her letters at the ward school and joined the watch. I am proud of her. I still tell her to eat before she starts checking my latch for the third time.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_berren_sorn","name":"Berren Sorn","mapId":"MORNAY_SORN_HOME_MAP","role":"child","category":"resident_or_visitor","x":6.5,"y":10.5,"spriteType":"child","text":"Aunt Hesta fixes boots downstairs. I wait up here till Mother finishes work. Aunt says my feet are repeat customers.","facing":"left"}),
  Object.freeze({"id":"mornay_cerra_muir","name":"Cerra Muir","mapId":"MORNAY_COURT_UNIT_2_MAP","role":"elder's caregiver","category":"resident_or_visitor","x":8.5,"y":7.5,"spriteType":"patron","text":"Etta tells the same story differently every afternoon. I put the kettle on and listen. There are worse ways to spend time than letting somebody remember a life.","facing":"right"}),
  Object.freeze({"id":"mornay_ilven_reed","name":"Ilven Reed","mapId":"MORNAY_REED_HOME_MAP","role":"homebound net maker","category":"worker","x":5.5,"y":9.5,"spriteType":"worker","text":"Heba brings the difficult nets here. I can't take the quay steps now, but I can still earn by my hands. The boats going toward Drynport carry a little of my work with them.","facing":"left","pose":"seated"}),
  Object.freeze({"id":"mornay_verna_quill","name":"Verna Quill","mapId":"MORNAY_COURT_UNIT_4_MAP","role":"Nessa's mother","category":"resident_or_visitor","x":6.5,"y":8.5,"spriteType":"patron","text":"Nessa learnt her sums counting laundry bundles here. Now she counts what the neighbours need. I wish she'd remember that her own supper belongs in the total.","facing":"left","pose":"seated"}),
]);

const MORNAY_COMPANION_EXCHANGES = Object.freeze({
  mornay_inessa_cray: [
    {speakerId:'esla',lines:['Calwick. We can identify our office without opening sealed material.']},
    {speakerId:'mornay_inessa_cray',lines:['Keep it sealed until the proper desk asks. That is at least one rule we agree on.']}
  ],
  mornay_yara_kelm: [
    {speakerId:'esla',lines:['Rest is unpopular advice. Usually well supported.']},
    {speakerId:'mornay_yara_kelm',lines:['You may borrow it for your travelling companion. The difficult part is getting it followed.']}
  ],
  mornay_elrin_vey: [
    {speakerId:'esla',lines:['A registration does not promise unlimited strength. I wish more people understood that.']},
    {speakerId:'mornay_elrin_vey',lines:['Selven does. That makes this ward possible.']}
  ],
  mornay_dena_mere: [
    {speakerId:'esla',lines:['A delay on a ledger can be a missed meal somewhere else.']},
    {speakerId:'mornay_dena_mere',lines:['Then you know why we count the days ourselves.']}
  ],
  mornay_nessa_quill: [
    {speakerId:'esla',lines:['The neighbours seem to know where help is needed.']},
    {speakerId:'mornay_nessa_quill',lines:['They live here. That is useful knowledge.']}
  ]
});
// Keep full names in the authored roster; dialogue uses first names, as in other towns.
const MORNAY_NPCS = MORNAY_RESIDENTS.map((r,index) => ({
  id:r.id, name:r.name.split(' ')[0],
  map:mornayContentKey(r.mapId),
  x:r.x*TILE,y:r.y*TILE,
  solid:true, spriteType:r.spriteType,
  facing:r.facing,
  get pose(){return r.dayOff && isDayOff() ? r.dayOff.pose : r.pose;},
  authoredPose:true,
  hairColor:r.hairColor || ['#392b25','#71604d','#a99d85','#594334'][index%4],
  coatColor:['#4d5d51','#615344','#4e5967','#73584c','#686454'][index%5],
  speakerId:r.id, flag_required:null, flag_sets:null,
  action:r.service ? 'mornayService' : null, service:r.service || null,
  movement:r.patrol ? {type:'patrol',autoStart:true,loop:true,speed:0.5,
    waypoints:r.route} : undefined,
  get dialogue() {
    const pages=[[r.text]],exchange=MORNAY_COMPANION_EXCHANGES[r.id];
    return exchange ? postMq5CompanionDialogue(pages,r.id,exchange) : pages;
  }
}));

// Schedules reuse the existing five-day calendar; no new saved state or duplicate NPC.
for (const r of MORNAY_RESIDENTS.filter(r=>r.dayOff)) {
  const npc=MORNAY_NPCS.find(n=>n.id===r.id);
  Object.defineProperty(npc,'map',{enumerable:true,configurable:true,
    get(){return mornayContentKey(isDayOff()?r.dayOff.mapId:r.mapId);}});
  Object.defineProperty(npc,'facing',{enumerable:true,configurable:true,
    get(){return isDayOff()?r.dayOff.facing:r.facing;}});
  for(const axis of ['x','y']) Object.defineProperty(npc,axis,{enumerable:true,configurable:true,
    get(){return (isDayOff()?r.dayOff[axis]:r[axis])*TILE;}});
}
